/* Penny prototype screens, part 1: shared helpers, transaction form, onboarding, home, review, transactions, budgets, envelopes, goals, accounts, categories, payees, rules. */
(function(PO){
const esc=PO.esc, $=PO.$, t=k=>PO.t(k);
const H = PO.H = {};
H.hdr = (title, sub, right='', back=null) => `<div class="hdr">${back?`<button class="back" data-act="back">‹ ${esc(back)}</button>`:''}<div style="min-width:0"><h2>${esc(title)}</h2>${sub?`<div class="sub">${sub}</div>`:''}</div><div>${right}</div></div>`;
H.empty = (title, body, action='') => `<div class="empty"><b>${esc(title)}</b>${esc(body)}${action?`<div style="margin-top:10px">${action}</div>`:''}</div>`;
H.err = (title, body, action='') => `<div class="card err"><b>${esc(title)}</b><div class="sub">${esc(body)}</div>${action?`<div style="margin-top:8px">${action}</div>`:''}</div>`;
H.loading = () => `<div class="card"><div class="skel" style="width:60%"></div><div class="skel"></div><div class="skel" style="width:80%"></div></div>`;
H.p = o => `data-p='${esc(JSON.stringify(o))}'`;
H.money = (minor, cur, o) => `<span class="amt ${minor>0&&o&&o.signed?'in':''}">${esc(PO.fmt(minor, cur, o))}</span>`;
H.kindSign = tk => ({expense:-1, income:1, refund:1, transfer:0, adjustment:0})[tk.kind] * (tk.kind==='adjustment'?(tk.dir==='in'?1:-1):1);
H.txRow = (x, o={}) => { const sel=PO.ui.sel.has(x.id); const sign = x.kind==='income'||x.kind==='refund'||(x.kind==='adjustment'&&x.dir==='in') ? 1 : x.kind==='transfer' ? 0 : -1; const hidden=!PO.visible(x);
  const main = hidden ? t('private') : (PO.payeeName(x) || (x.kind==='transfer' ? `${PO.acctName(x.acct)} → ${PO.acctName(x.toAcct)}` : PO.catName(x.cat)));
  const meta = [x.kind==='transfer'?t('transfer'):x.kind==='adjustment'?t('adjustment'):x.kind==='refund'?t('refund'):PO.catPath(x.cat), PO.acctName(x.acct), o.showDate?PO.relDate(x.date):null, x.status&&x.status!=='cleared'?t(x.status):null, x.splits&&x.splits.length?`${x.splits.length} splits`:null, x.attachments&&x.attachments.length?'📎':null, x.private?'🔒':null].filter(Boolean).join(' · ');
  return `<div class="row ${sel?'sel':''}" role="button" tabindex="0" data-act="tx-open" data-id="${x.id}" aria-label="${esc(main)} ${esc(PO.fmt(x.amt,x.cur))}"><div style="min-width:0"><div class="t">${esc(main)}</div><div class="m">${esc(meta)}</div></div><div style="display:flex;align-items:center;gap:8px">${H.money(sign*x.amt, x.cur, {signed:true, plus:true})}${o.select?`<button class="ic-btn" data-act="tx-sel" data-id="${x.id}" aria-label="Select" aria-pressed="${sel}">${sel?'☑':'☐'}</button>`:''}</div></div>`; };
H.catOptions = (kind, cur) => { const list=PO.list('cats').filter(c=>!c.archived && c.kind===(kind==='income'?'income':'expense')); const roots=list.filter(c=>!c.parent); const out=[]; roots.forEach(r=>{ out.push({v:r.id,l:r.name}); list.filter(c=>c.parent===r.id).forEach(c=>{ out.push({v:c.id,l:`   ${c.name}`}); list.filter(g=>g.parent===c.id).forEach(g=>out.push({v:g.id,l:`      ${g.name}`})); }); }); return out; };
H.acctOptions = (exclude) => PO.list('accts').filter(a=>!a.archived && a.id!==exclude).map(a=>({v:a.id,l:`${a.name} (${a.cur})`}));
H.bar = (spent, limit) => { const p=limit>0?Math.min(100,Math.round(spent/limit*100)):(spent>0?100:0); const cls=limit>0&&spent/limit>=1?'over':limit>0&&spent/limit>=0.8?'warn':''; return `<div class="bar"><i class="${cls}" style="width:${p}%"></i></div>`; };
H.periodNav = (p, screen, params={}) => `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px"><button class="ic-btn" data-go="${screen}" ${H.p({...params, period:PO.shiftPeriod(p,-1,PO.cycle(),PO.ctx()).start})} aria-label="Previous period">‹</button><div style="text-align:center;min-width:0"><b>${esc(PO.periodLabel(p))}</b><div class="sub">${esc(PO.cycleName(PO.cycle()))}${p.start>PO.today()?' · future':p.end<PO.today()?' · past':''}</div></div><button class="ic-btn" data-go="${screen}" ${H.p({...params, period:PO.shiftPeriod(p,1,PO.cycle(),PO.ctx()).start})} aria-label="Next period">›</button></div>`;
H.periodFromParams = params => params.period ? PO.periodOf(params.period) : PO.curPeriod();
H.afterWrite = (msg, gid) => { PO.render(); PO.toast(msg, gid); try{ const fresh=PO.fireAlerts(); if(fresh.length) PO.notify(fresh[0]); }catch(e){ console.error(e); } };
PO.ACT.back = () => PO.back();

/* ---------- transaction form (create, edit, split, attach, duplicate, delete) */
PO.txForm = (tx={}, o={}) => {
  const isNew=!tx.id; const cur=tx.cur||PO.cur(); const space=PO.profile().kind==='space';
  if(!isNew && !PO.can('edit', tx)){ PO.toast('Your role cannot edit this transaction'); return; }
  const values={ kind:tx.kind||o.kind||'expense', amt:tx.amt??null, acct:tx.acct||PO.profile().defaultAcct||(PO.list('accts')[0]||{}).id, toAcct:tx.toAcct||'', toAmt:tx.toAmt??null, dir:tx.dir||'out', cat:tx.cat||'', payee:PO.payeeName(tx)||'', date:tx.date||PO.today(), time:tx.time||'', note:tx.note||'', tags:(tx.tags||[]).join(', '), status:tx.status||'cleared', private:!!tx.private, exclude:!!tx.excludeBudget, files:tx.attachments||[], splits:PO.clone(tx.splits||[]), shareTo:'' , _dupeAck:false };
  const payees=PO.list('payees').map(p=>p.name);
  const toCur = v => (PO.get('accts',v.toAcct)||{}).cur;
  const spec = { title: isNew ? t('add_spend') : `${t('edit')} · ${PO.relDate(tx.date)}`, values,
    intro: tx.status==='reconciled' ? 'This transaction is reconciled. Saving changes will mark it cleared again.' : (isNew && o.fromReview ? 'Captured item. Check the category, then save to post it.' : ''),
    fields: [
      {k:'kind', label:'Type', type:'chips', options:[{v:'expense',l:t('expense')},{v:'income',l:t('income')},{v:'transfer',l:t('transfer')},{v:'refund',l:t('refund')},{v:'adjustment',l:t('adjustment')}], required:true},
      {k:'amt', label:`${t('amount')} (${cur})`, type:'money', cur, required:true, autofocus:isNew},
      {k:'acct', label:v=>v.kind==='transfer'?t('from'):t('account'), type:'select', options:H.acctOptions(), required:true},
      {k:'toAcct', label:t('to'), type:'select', options:[{v:'',l:'Choose account'},...H.acctOptions()], hidden:v=>v.kind!=='transfer', validate:(v,all)=>all.kind==='transfer'&&(!v||v===all.acct)?'Choose a different destination account':null},
      {k:'toAmt', label:'Amount received (destination currency)', type:'money', cur:toCur(values)||cur, hidden:v=>v.kind!=='transfer'||!v.toAcct||toCur(v)===cur, hint:'Rate on this date is prefilled; override if the bank used another.'},
      {k:'dir', label:'Direction', type:'chips', options:[{v:'out',l:'Decrease balance'},{v:'in',l:'Increase balance'}], hidden:v=>v.kind!=='adjustment'},
      {k:'cat', label:t('category'), type:'select', options:v=>[{v:'',l:t('uncategorised')},...H.catOptions(v.kind)], hidden:v=>v.kind==='transfer'},
      {k:'payee', label:t('payee'), type:'text', datalist:payees, placeholder:'Shop, person or app', hidden:v=>v.kind==='transfer'||v.kind==='adjustment'},
      {k:'date', label:t('date'), type:'date', required:true, hint:`Moves the budget period with it. Timezone: ${PO.profile().tz}`},
      {k:'time', label:t('time'), type:'time'},
      {k:'note', label:t('note'), type:'text'},
      {k:'tags', label:t('tags'), type:'text', placeholder:'reimbursable, trip', datalist:PO.list('tags').map(x=>x.name)},
      {k:'status', label:t('status'), type:'chips', options:[{v:'pending',l:t('pending')},{v:'cleared',l:t('cleared')},{v:'reconciled',l:t('reconciled')}]},
      {k:'splits', label:t('split'), type:'html', html:v=>`<div class="row" style="border-top:0;padding:4px 0"><div><div class="t">${t('split')} across categories</div><div class="m">${v.splits&&v.splits.length?v.splits.map(s=>`${PO.catName(s.cat)} ${PO.fmt(s.amt,cur,{force:true})}`).join(' · '):'Whole amount goes to one category'}</div></div><button type="button" class="btn sm ghost" data-act="form-action" data-k="split">${v.splits&&v.splits.length?t('edit'):t('split')}</button></div>`, hidden:v=>v.kind==='transfer'},
      {k:'files', label:'Attachments (camera, gallery, files)', type:'file'},
      {k:'private', label:t('private'), type:'toggle', hint:'Amount counts in totals; details hidden from other members', hidden:()=>!space},
      {k:'exclude', label:'Exclude from budgets and reports', type:'toggle'},
      {k:'shareTo', label:'Also post to a shared space', type:'select', options:[{v:'',l:'No'},...Object.values(PO.state.profiles).filter(p=>p.kind==='space'&&p.id!==PO.state.currentProfile).map(p=>({v:p.id,l:p.name}))], hidden:v=>space||!isNew||!Object.values(PO.state.profiles).some(p=>p.kind==='space')}
    ].map(f=>({...f, label: typeof f.label==='function'?f.label(values):f.label, options: typeof f.options==='function'?f.options(values):f.options})),
    onChange:(ev, form, vals)=>{ const changedKind = vals.kind!==spec.values.kind; const changedTo = vals.toAcct!==spec.values.toAcct; Object.assign(spec.values, vals); if(changedKind||changedTo){ if(changedKind){ spec.values.cat=''; } if(changedTo && vals.toAcct && toCur(vals)!==cur && vals.amt) spec.values.toAmt=PO.convert(vals.amt,cur,toCur(vals)); spec.fields.forEach(f=>{ if(f.k==='cat') f.options=[{v:'',l:t('uncategorised')},...H.catOptions(spec.values.kind)]; if(f.k==='toAmt') f.cur=toCur(spec.values)||cur; if(f.k==='acct') f.label=spec.values.kind==='transfer'?t('from'):t('account'); }); PO.rerenderSheet(); }
      if(ev.target && ev.target.name==='payee' && isNew && !spec.values.cat){ const sug=PO.suggestCat(vals.payee); if(sug){ spec.values.cat=sug; const sel=form.querySelector('select[name=cat]'); if(sel) sel.value=sug; } } },
    actions:[ {k:'split', label:'', run:(vals)=>{ Object.assign(spec.values, vals); PO.splitForm(spec, cur); }}, ...(isNew?[]:[{k:'dup', label:t('duplicate'), run:()=>{ PO.closeSheet(); const cp={...PO.clone(tx), id:undefined, date:PO.today(), status:'cleared'}; delete cp.id; delete cp.created_at; PO.txForm(cp); }}, {k:'hist', label:t('history'), run:()=>{ PO.closeSheet(); PO.go('history',{ent:'tx', id:tx.id}); }}]) ],
    validate:(v)=>{ const e={}; if(v.kind!=='transfer' && v.splits && v.splits.length){ const sum=v.splits.reduce((s,x)=>s+x.amt,0); if(sum>v.amt) e._form=`Splits (${PO.fmt(sum,cur,{force:true})}) exceed the amount`; } if(v.date>PO.addDays(PO.today(),366)) e.date='More than a year ahead; use a recurring item instead'; return Object.keys(e).length?e:null; },
    onSave:(v)=>{ v.splits = spec.values.splits||[]; const payeeId = (v.kind!=='transfer'&&v.kind!=='adjustment'&&v.payee) ? PO.ensurePayee(v.payee) : null;
      const draft={ kind:v.kind, amt:v.amt, cur, acct:v.acct, toAcct:v.kind==='transfer'?v.toAcct:null, toAmt:v.kind==='transfer'&&v.toAcct&&toCur(v)!==cur?(v.toAmt||PO.convert(v.amt,cur,toCur(v))):null, dir:v.kind==='adjustment'?v.dir:null, cat:v.kind==='transfer'?null:(v.cat||'uncat'), payeeId, payee:v.payee||'', date:v.date, time:v.time||'', note:v.note||'', tags:v.tags.split(',').map(s=>s.trim()).filter(Boolean), status:tx.status==='reconciled'&&v.status==='reconciled'?'cleared':v.status, private:!!v.private, excludeBudget:!!v.exclude, attachments:v.files||[], splits:v.splits, source:tx.source||'manual' };
      if(draft.splits.length){ const sum=draft.splits.reduce((s,x)=>s+x.amt,0); if(sum<draft.amt) draft.splits.push({cat:draft.cat, amt:draft.amt-sum}); }
      if(isNew && !spec.values._dupeAck){ const d=PO.findDupes({...draft, id:'new'}); if(d.length){ spec.values={...spec.values, ...v, _dupeAck:true}; spec.intro=`Possible duplicate of ${PO.payeeName(d[0])||PO.catName(d[0].cat)} ${PO.fmt(d[0].amt,d[0].cur,{force:true})} on ${PO.relDate(d[0].date)}. Save again to keep both, or close to cancel.`; PO.rerenderSheet(); PO.announce(spec.intro); return false; } }
      draft.tags.forEach(tg=>{ if(!PO.list('tags').find(x=>x.name===tg)) PO.commit('tags',PO.uid('tg'),{name:tg},'auto'); });
      let id=tx.id||PO.uid('t'); const gid=PO.group(()=>{ PO.commit('tx', id, draft, isNew?'create':'edit'); if(v.shareTo){ const prev=PO.state.currentProfile; PO.state.currentProfile=v.shareTo; const sp=PO.profile(); const cat=draft.cat&&PO.list('cats').find(c=>c.key===(PO.get('cats',draft.cat)||{}).key); PO.commit('tx', PO.uid('t'), {...draft, acct:sp.defaultAcct||(PO.list('accts')[0]||{}).id, cat:cat?cat.id:'uncat', mirrorOf:id, profileId:v.shareTo},'mirror'); PO.audit(`Mirrored ${PO.fmt(draft.amt,cur,{force:true})} from a personal book`); PO.state.currentProfile=prev; } });
      if(draft.cat && draft.cat!=='uncat' && draft.payee) { const learned=PO.learn(draft.payee, draft.cat); if(learned==='enabled') setTimeout(()=>PO.toast(`Rule learned: ${draft.payee} → ${PO.catName(draft.cat)}`),2600); }
      if(space) PO.audit(`${isNew?'Added':'Edited'} ${PO.fmt(draft.amt,cur,{force:true})} ${draft.payee?'at '+draft.payee:''}`);
      if(o.onSaved) o.onSaved(id);
      H.afterWrite(isNew?`Added ${PO.fmt(draft.amt,cur,{force:true})}${draft.cat?' to '+PO.catName(draft.cat):''}`:'Saved. Previous version kept in history.', gid); },
    onDelete: isNew?null:()=>{ if(!PO.can('delete',tx)){ PO.toast('Your role cannot delete this'); return; } const gid=PO.group(()=>PO.remove('tx',tx.id)); if(space) PO.audit(`Deleted ${PO.fmt(tx.amt,tx.cur,{force:true})}`); H.afterWrite('Deleted. In Trash for 30 days.', gid); },
    footer: isNew ? 'Nothing except amount and account is mandatory.' : 'Edits are versions; see History to revert.' };
  PO.form(spec); };
PO.splitForm = (parent, cur) => { const splits=PO.clone(parent.values.splits||[]); const total=parent.values.amt||0;
  const render=()=>{ PO.openSheet('splits', {splits, total, cur, onDone:(list)=>{ parent.values.splits=list; PO.closeSheet(); PO.rerenderSheet(); }}); };
  render(); };
PO.SHEETS.splits = { label:'Split', render:d=>{ const sum=d.splits.reduce((s,x)=>s+x.amt,0); return `<b>${t('split')}</b><p class="sub">Total ${PO.fmt(d.total,d.cur,{force:true})}. Assigned ${PO.fmt(sum,d.cur,{force:true})}; the remainder stays on the main category.</p><div class="list">${d.splits.map((s,i)=>`<div class="row"><div><div class="t">${esc(PO.catName(s.cat))}</div><div class="m">${esc(s.note||'')}</div></div><div style="display:flex;gap:6px;align-items:center">${H.money(s.amt,d.cur,{force:true})}<button class="ic-btn" data-act="split-rm" data-i="${i}">×</button></div></div>`).join('')||H.empty('No splits yet','Add a part below.')}</div><div class="card" style="background:var(--sunk);margin-top:10px"><div class="field"><label for="sp-cat">${t('category')}</label><select id="sp-cat">${H.catOptions('expense').map(o=>`<option value="${esc(o.v)}">${esc(o.l)}</option>`).join('')}</select></div><div class="field"><label for="sp-amt">${t('amount')}</label><input id="sp-amt" class="inp" inputmode="decimal" placeholder="${PO.fmt(Math.max(0,d.total-sum),d.cur,{force:true,noSym:true})}"></div><button class="btn sm" data-act="split-add">Add part</button></div><div style="display:flex;gap:8px;margin-top:10px"><button class="btn" style="flex:1" data-act="split-done">${t('done')}</button><button class="btn sm ghost" data-act="split-equal">Split equally with main</button></div>`; } };
PO.ACT['split-add'] = () => { const s=PO.ui.sheets[PO.ui.sheets.length-1].data; const cat=$('#sp-cat').value; const raw=$('#sp-amt').value.trim(); const major=raw?PO.evalAmount(raw):PO.toMajor(Math.max(0,s.total-s.splits.reduce((a,x)=>a+x.amt,0)),s.cur); const err=PO.validateAmount(major,s.cur); if(err){ PO.toast(err); return; } const amt=PO.toMinor(major,s.cur); if(s.splits.reduce((a,x)=>a+x.amt,0)+amt>s.total){ PO.toast('That exceeds the total'); return; } s.splits.push({cat, amt}); PO.rerenderSheet(); };
PO.ACT['split-rm'] = b => { const s=PO.ui.sheets[PO.ui.sheets.length-1].data; s.splits.splice(Number(b.dataset.i),1); PO.rerenderSheet(); };
PO.ACT['split-equal'] = () => { const s=PO.ui.sheets[PO.ui.sheets.length-1].data; const cat=$('#sp-cat').value; s.splits=[{cat, amt:Math.floor(s.total/2)}]; PO.rerenderSheet(); };
PO.ACT['split-done'] = () => { const s=PO.ui.sheets[PO.ui.sheets.length-1].data; s.onDone(s.splits); };
PO.ACT['tx-open'] = b => { const x=PO.get('tx',b.dataset.id); if(!x) return; if(PO.ui.sel.size){ PO.ACT['tx-sel'](b); return; } if(!PO.visible(x)){ PO.toast('This transaction is private to another member'); return; } PO.txForm(x); };
PO.ACT['tx-sel'] = b => { const id=b.dataset.id; if(PO.ui.sel.has(id)) PO.ui.sel.delete(id); else PO.ui.sel.add(id); PO.render(); };
PO.ACT['sel-clear'] = () => { PO.ui.sel.clear(); PO.render(); };
PO.ACT['bulk'] = b => { const ids=[...PO.ui.sel]; const what=b.dataset.k; if(what==='delete'){ const gid=PO.group(()=>ids.forEach(id=>PO.remove('tx',id))); PO.ui.sel.clear(); H.afterWrite(`Deleted ${ids.length}`, gid); return; }
  if(what==='cat'){ PO.form({title:`Change category for ${ids.length}`, fields:[{k:'cat',label:t('category'),type:'select',options:H.catOptions('expense'),required:true}], onSave:v=>{ const gid=PO.group(()=>ids.forEach(id=>PO.commit('tx',id,{cat:v.cat,splits:[]},'bulk'))); PO.ui.sel.clear(); H.afterWrite('Updated', gid); }}); }
  if(what==='acct'){ PO.form({title:`Move ${ids.length} to account`, fields:[{k:'acct',label:t('account'),type:'select',options:H.acctOptions(),required:true}], onSave:v=>{ const gid=PO.group(()=>ids.forEach(id=>PO.commit('tx',id,{acct:v.acct},'bulk'))); PO.ui.sel.clear(); H.afterWrite('Moved', gid); }}); }
  if(what==='tag'){ PO.form({title:`Tag ${ids.length}`, fields:[{k:'tag',label:'Tag',type:'text',required:true,datalist:PO.list('tags').map(x=>x.name)}], onSave:v=>{ const gid=PO.group(()=>ids.forEach(id=>{ const x=PO.get('tx',id); PO.commit('tx',id,{tags:[...new Set([...(x.tags||[]),v.tag.trim()])]},'bulk'); })); PO.ui.sel.clear(); H.afterWrite('Tagged', gid); }}); }
  if(what==='date'){ PO.form({title:`Re-date ${ids.length}`, fields:[{k:'date',label:t('date'),type:'date',required:true}], onSave:v=>{ const gid=PO.group(()=>ids.forEach(id=>PO.commit('tx',id,{date:v.date},'bulk'))); PO.ui.sel.clear(); H.afterWrite('Re-dated', gid); }}); }
  if(what==='merge'){ if(ids.length!==2){ PO.toast('Select exactly two to merge duplicates'); return; } const [a,b2]=ids.map(id=>PO.get('tx',id)); const keep=a.created_at<b2.created_at?a:b2, drop=keep===a?b2:a; const gid=PO.group(()=>{ PO.commit('tx',keep.id,{sources:[...(keep.sources||[keep.source]), drop.source], note:[keep.note,drop.note].filter(Boolean).join(' / ')},'merge'); PO.remove('tx',drop.id,'merge'); }); PO.ui.sel.clear(); H.afterWrite('Merged into one transaction', gid); } };

/* ---------- quick add sheet (keypad, chips, calculator) */
PO.SHEETS.add = { label:'Quick add', render:(d)=>{ if(d.full){ setTimeout(()=>{ PO.closeSheet(); PO.txForm({}, {}); },0); return ''; } d.amt=d.amt||''; d.kind=d.kind||'expense'; d.acct=d.acct||PO.profile().defaultAcct||(PO.list('accts')[0]||{}).id; const cur=PO.cur(); const pk=PO.pack(); const hour=new Date().getHours(); const recent=[...new Set(PO.list('tx').filter(x=>x.kind==='expense').sort((a,b)=>b.date.localeCompare(a.date)).map(x=>x.cat))]; const roots=PO.list('cats').filter(c=>!c.parent&&c.kind===(d.kind==='income'?'income':'expense')&&!c.excluded&&!c.archived); const order=[...recent.map(id=>PO.get('cats',id)).filter(Boolean), ...roots]; const byRoot={}; order.forEach(c=>{ const r=PO.catRoot(c.id); if(!byRoot[r]) byRoot[r]=c; }); let chips=Object.values(byRoot); if(hour<11){ const eat=chips.find(c=>PO.catRoot(c.id).endsWith(':eat')); if(eat){ chips=[eat,...chips.filter(c=>c!==eat)]; } } chips=chips.slice(0,6); const v=PO.evalAmount(d.amt); const valid=isFinite(v)&&v>0;
  return `<div style="display:flex;justify-content:space-between;align-items:center"><b>${t('quick_add')}</b><div style="display:flex;gap:6px"><button class="pill" data-act="add-full">${t('more')}</button><button class="pill" data-act="sheet-close">${t('close')}</button></div></div>
  <div class="chips" style="margin-top:8px">${['expense','income','transfer'].map(k=>`<button class="chip small" data-act="add-kind" data-v="${k}" aria-pressed="${d.kind===k}">${t(k)}</button>`).join('')}</div>
  <div class="amtbox" aria-live="polite"><span>${esc(PO.sym(cur))}</span>${esc(d.amt||'0')}<small>${d.amt&&/[+\-*\/×÷%]/.test(d.amt.slice(1))?(valid?`= ${PO.fmt(PO.toMinor(v,cur),cur,{force:true})}`:'…'):(`decimal ${PO.decSep()} · grouping ${PO.groupSep()}`)}</small></div>
  <div class="chips" style="justify-content:center">${pk.chips.map(c=>`<button class="chip small" data-act="add-chip" data-v="${c}">${esc(new Intl.NumberFormat(PO.numLocale()).format(c))}</button>`).join('')}</div>
  ${d.kind!=='transfer'?`<div class="sec">${t('category')}</div><div class="chips">${chips.map(c=>`<button class="chip" data-act="add-cat" data-v="${c.id}" aria-pressed="${d.cat===c.id}">${esc(c.name)}</button>`).join('')}<button class="chip" data-act="add-full">${t('more')}…</button></div>`:''}
  <div class="sec">${d.kind==='transfer'?t('from'):t('account')}</div><div class="chips">${PO.list('accts').filter(a=>!a.archived).map(a=>`<button class="chip small" data-act="add-acct" data-v="${a.id}" aria-pressed="${d.acct===a.id}">${esc(a.name)}</button>`).join('')}</div>
  ${d.kind==='transfer'?`<div class="sec">${t('to')}</div><div class="chips">${PO.list('accts').filter(a=>!a.archived&&a.id!==d.acct).map(a=>`<button class="chip small" data-act="add-to" data-v="${a.id}" aria-pressed="${d.toAcct===a.id}">${esc(a.name)}</button>`).join('')}</div>`:''}
  <div class="kp">${['7','8','9','÷','4','5','6','×','1','2','3','−','.','0','⌫','+'].map(k=>`<button data-act="add-key" data-v="${k}" class="${'÷×−+'.includes(k)?'op':''}" aria-label="${k==='⌫'?'Backspace':k}">${k==='.'?esc(PO.decSep()):k}</button>`).join('')}</div>
  <div style="display:flex;gap:8px;margin-top:12px;align-items:center"><button class="chip" data-act="add-voice" aria-label="Voice entry">🎤</button><button class="chip" data-act="add-full" aria-label="Receipt">📷</button><button class="btn" style="flex:1" data-act="add-save" ${valid?'':'disabled'}>${t('save')}</button></div>
  <div class="sub" style="text-align:center;margin-top:8px">Long-press + for the full form: payee, date, split, tags, attachments.</div>`; } };
const addData = () => PO.ui.sheets[0] && PO.ui.sheets[0].kind==='add' ? PO.ui.sheets[0].data : null;
PO.ACT['add-key'] = b => { const d=addData(); if(!d) return; const k=b.dataset.v; if(k==='⌫') d.amt=d.amt.slice(0,-1); else if(k==='.'){ d.amt+=PO.decSep(); } else if(d.amt.length<18) d.amt+=k; PO.rerenderSheet(); };
PO.ACT['add-chip'] = b => { const d=addData(); d.amt=String(b.dataset.v); PO.rerenderSheet(); };
PO.ACT['add-cat'] = b => { const d=addData(); d.cat=b.dataset.v; PO.rerenderSheet(); };
PO.ACT['add-acct'] = b => { const d=addData(); d.acct=b.dataset.v; PO.rerenderSheet(); };
PO.ACT['add-to'] = b => { const d=addData(); d.toAcct=b.dataset.v; PO.rerenderSheet(); };
PO.ACT['add-kind'] = b => { const d=addData(); d.kind=b.dataset.v; d.cat=null; PO.rerenderSheet(); };
PO.ACT['add-full'] = () => { const d=addData()||{}; const cur=PO.cur(); const v=PO.evalAmount(d.amt||''); PO.closeSheet(); PO.txForm({kind:d.kind, amt:isFinite(v)&&v>0?PO.toMinor(v,cur):null, acct:d.acct, cat:d.cat, toAcct:d.toAcct}); };
PO.ACT['add-voice'] = () => { PO.form({title:'Voice entry (typed stand-in)', intro:'On a phone this is on-device speech. Type what you would say, in any mix of languages.', fields:[{k:'say',label:'Say',type:'text',placeholder:'chai 20 cash',autofocus:true,required:true}], saveLabel:'Parse', onSave:v=>{ const p=PO.parseShareText(v.say); const num=v.say.match(/(\d+(?:[.,]\d+)?)/); const amt=p.amt||(num?parseFloat(num[1].replace(',','.')):null); const words=v.say.toLowerCase(); const cat=PO.list('cats').find(c=>!c.archived&&words.includes(c.name.toLowerCase().split(' ')[0]))||null; const acct=PO.list('accts').find(a=>words.includes(a.name.toLowerCase().split(' ')[0])); const payee=v.say.replace(/\d+([.,]\d+)?/,'').replace(/\b(cash|card|upi|gcash|for|to|at|paid|spent|rupees|pesos|dollars)\b/gi,'').trim(); PO.closeSheet(); PO.txForm({kind:p.kind, amt:amt?PO.toMinor(amt,PO.cur()):null, cat:cat?cat.id:PO.suggestCat(payee)||'', payee, acct:acct?acct.id:undefined}); }}); };
PO.ACT['add-save'] = () => { const d=addData(); const cur=PO.cur(); const v=PO.evalAmount(d.amt); const err=PO.validateAmount(v,cur); if(err){ PO.toast(err); return; } if(d.kind==='transfer'&&(!d.toAcct||d.toAcct===d.acct)){ PO.toast('Pick a destination account'); return; } const amt=PO.toMinor(v,cur); const draft={kind:d.kind, amt, cur, acct:d.acct, toAcct:d.kind==='transfer'?d.toAcct:null, toAmt:null, cat:d.kind==='transfer'?null:(d.cat||'uncat'), payee:'', payeeId:null, date:PO.today(), time:PO.nowHM(), status:'cleared', source:'manual', tags:[], splits:[], attachments:[]}; if(d.kind==='transfer'){ const tc=(PO.get('accts',d.toAcct)||{}).cur; if(tc&&tc!==cur) draft.toAmt=PO.convert(amt,cur,tc); } const dupes=PO.findDupes({...draft,id:'new'}); if(dupes.length && !d.dupeAck){ d.dupeAck=true; PO.toast(`Looks like ${PO.fmt(dupes[0].amt,cur,{force:true})} on ${PO.relDate(dupes[0].date)}. Tap Save again to keep both.`); return; } const id=PO.uid('t'); const gid=PO.group(()=>PO.commit('tx',id,draft)); PO.closeSheet(); if(PO.profile().kind==='space') PO.audit(`Added ${PO.fmt(amt,cur,{force:true})}`); H.afterWrite(`Added ${PO.fmt(amt,cur,{force:true})}${draft.cat&&draft.cat!=='uncat'?' to '+PO.catName(draft.cat):''}`, gid); };

/* ---------- onboarding */
PO.SCREENS.onboarding = { render:(pr)=>{ const d=PO.ui.ob||(PO.ui.ob={step:1, region:PO.profile().region, lang:PO.state.settings.lang, cycle:PO.clone(PO.cycle()), cash:PO.toMajor(PO.balance(PO.list('accts').find(a=>a.type==='cash')?.id||'',null),PO.cur())||0}); const pk=PO.PACKS[d.region]; const dots=`<div class="dots" style="display:flex;gap:6px;justify-content:center;margin:6px 0 14px">${[1,2,3].map(i=>`<i style="width:8px;height:8px;border-radius:50%;background:${d.step===i?'var(--accent)':'var(--line)'}"></i>`).join('')}</div>`;
    if(d.step===1) return `${dots}<div class="hdr"><h2>Where do you keep your money?</h2></div><p class="sub">Sets currency, number format, pay cycle default, payment apps and holidays. All changeable later.</p><div class="field"><label for="ob-region">Region</label><select id="ob-region" data-act="ob-region">${Object.values(PO.PACKS).map(p=>`<option value="${p.id}" ${p.id===d.region?'selected':''}>${esc(p.name)} · ${p.cur}</option>`).join('')}</select></div><div class="sec">${t('language')}</div><div class="chips">${pk.langs.map(l=>`<button class="chip" data-act="ob-lang" data-v="${l}" aria-pressed="${d.lang===l}">${esc(PO.LANGS[l]||l)}</button>`).join('')}</div><div class="sub" style="margin-top:8px">Numbers: ${esc(new Intl.NumberFormat(pk.numbering==='in'?'en-IN':pk.locale).format(1234567.5))} · ${PO.PACKS[d.region].cur} has ${PO.dec(pk.cur)} decimals</div><div style="height:18px"></div><button class="btn" data-act="ob-next">Continue</button><div style="height:8px"></div><button class="btn ghost" data-act="ob-skip">Skip setup</button>`;
    if(d.step===2){ const opts=[['monthly','Monthly','Resets on your salary day'],['semimonthly','Twice a month','15th and last day (kinsenas, quincena)'],['weekly','Weekly','Daily-wage and gig income'],['biweekly','Every two weeks','US and Australian paydays'],['fourweekly','Every four weeks','Some UK employers'],['onincome','When money lands','Remittance and irregular income']]; const def=pk.cycle.type; const sorted=[...opts].sort((a,b)=>(a[0]===def?-1:b[0]===def?1:0)); return `${dots}<div class="hdr"><h2>When does money come in?</h2></div><p class="sub">Your budget resets on this cycle, not on the calendar month. Default for ${esc(pk.name)} is first.</p>${sorted.map(([v,n,dd])=>`<button class="opt" data-act="ob-cycle" data-v="${v}" aria-pressed="${d.cycle.type===v}"><span><b>${n}</b><div class="d">${dd}</div></span></button>`).join('')}${d.cycle.type==='monthly'?`<div class="field"><label for="ob-day">Salary day</label><input id="ob-day" type="number" min="1" max="31" value="${d.cycle.day||1}" data-act="ob-day"></div>`:''}${d.cycle.type==='onincome'?`<div class="field"><label for="ob-thr">Counts as "money landed" above</label><input id="ob-thr" type="number" value="${PO.toMajor(d.cycle.threshold||0,pk.cur)}" data-act="ob-thr"></div>`:''}<div style="height:12px"></div><button class="btn" data-act="ob-next">Continue</button><div style="height:8px"></div><button class="btn ghost" data-act="ob-back">Back</button>`; }
    return `${dots}<div class="hdr"><h2>Start with the cash in your pocket</h2></div><p class="sub">Banks and wallets can be added or imported any time. Cash is where tracking usually breaks, so we start there.</p><div class="card"><div class="field"><label for="ob-cash">Cash on hand (${esc(pk.cur)})</label><input id="ob-cash" class="inp" inputmode="decimal" value="${esc(String(d.cash))}" data-act="ob-cash"></div><button class="btn sm ghost" data-act="ob-import">Import from another app instead</button></div><button class="btn" data-act="ob-finish">Open ${PO.BRAND}</button><div style="height:8px"></div><button class="btn ghost" data-act="ob-back">Back</button><p class="sub" style="text-align:center;margin-top:10px">Joining a household? Open the invite link after setup.</p>`; } };
PO.ACT['ob-region'] = b => { const d=PO.ui.ob; d.region=b.value; d.lang=PO.PACKS[b.value].lang; d.cycle=PO.clone(PO.PACKS[b.value].cycle); PO.render(); };
document.addEventListener('change', ev=>{ const a=ev.target.dataset.act; if(a==='ob-region') PO.ACT['ob-region'](ev.target); if(a==='ob-day'){ PO.ui.ob.cycle.day=Math.max(1,Math.min(31,Number(ev.target.value)||1)); } if(a==='ob-thr'){ PO.ui.ob.cycle.threshold=PO.toMinor(Number(ev.target.value)||0, PO.PACKS[PO.ui.ob.region].cur); } if(a==='ob-cash'){ PO.ui.ob.cash=ev.target.value; } });
PO.ACT['ob-lang'] = b => { PO.ui.ob.lang=b.dataset.v; PO.render(); };
PO.ACT['ob-cycle'] = b => { const v=b.dataset.v; const d=PO.ui.ob; const pk=PO.PACKS[d.region]; d.cycle = v==='semimonthly'?{type:v,days:[15,'last']} : v==='monthly'?{type:v,day:pk.cycle.day||1} : v==='weekly'?{type:v,weekday:pk.weekStart} : v==='biweekly'||v==='fourweekly'?{type:v,anchor:PO.today()} : v==='onincome'?{type:v,threshold:0} : {type:v}; PO.render(); };
PO.ACT['ob-next'] = () => { PO.ui.ob.step=Math.min(3,PO.ui.ob.step+1); PO.render(); };
PO.ACT['ob-back'] = () => { PO.ui.ob.step=Math.max(1,PO.ui.ob.step-1); PO.render(); };
PO.ACT['ob-skip'] = PO.ACT['ob-finish'] = () => { const d=PO.ui.ob; const p=PO.profile(); const pk=PO.PACKS[d.region]; if(p.region!==d.region){ PO.state=PO.seed(d.region); } PO.profile().cycle=d.cycle; PO.state.settings.lang=d.lang; const cash=PO.list('accts').find(a=>a.type==='cash'); const major=PO.evalAmount(String(d.cash)); if(cash && isFinite(major)){ const target=PO.toMinor(major,cash.cur); const diff=target-PO.balance(cash.id); if(diff!==0) PO.commit('tx',PO.uid('t'),{kind:'adjustment',dir:diff>0?'in':'out',amt:Math.abs(diff),cur:cash.cur,acct:cash.id,cat:PO.cid(PO.state.currentProfile,'adj'),date:PO.today(),note:'Opening count',status:'cleared',source:'onboarding'},'create'); } PO.state.settings.onboarded=true; PO.save(); PO.ui.ob=null; PO.go('home',{},{replace:true}); PO.toast(t('welcome')); };
PO.ACT['ob-import'] = () => { PO.state.settings.onboarded=true; PO.save(); PO.ui.ob=null; PO.go('importer',{}); };

/* ---------- home */
PO.SCREENS.home = { render:()=>{ const p=PO.curPeriod(); const pc=PO.pace(p); const s=PO.safeToSpend(p); const spent=PO.spentTotal(p); const budgetable=PO.incomeIn(p)+PO.expectedIncome(p)-PO.committed(p)-PO.goalContribIn(p); const warn = budgetable>0 && spent/budgetable > pc.share+0.08; const today=PO.list('tx').filter(x=>x.date===PO.today()).sort((a,b)=>(b.time||'').localeCompare(a.time||'')); const review=PO.list('review'); const alerts=PO.computeAlerts(); const prof=PO.profile(); const role=PO.role();
  return `<div class="hdr"><div style="display:flex;align-items:center;gap:10px"><button class="avatar" data-go="profiles" aria-label="${t('profiles')}">${esc(prof.name[0])}</button><div><h2 style="font-size:18px">${esc(prof.name)}</h2><div class="sub">${esc(PO.periodLabel(p))} · ${pc.left} ${t('days_left')}${prof.kind==='space'?` · ${t('role')}: ${role}`:''}</div></div></div><div style="display:flex;gap:6px"><button class="ic-btn" data-act="toggle-hide" aria-label="Hide amounts">${PO.state.settings.hideAmounts?'👁':'👁‍🗨'}</button><button class="ic-btn" data-go="settings">${t('settings')}</button></div></div>
  <div class="hero ${warn?'warn':''}"><div class="lbl">${t('safe')} · ${pc.left} ${t('days_left')}</div><div class="big">${esc(PO.fmt(s))}</div><div class="line">${esc(PO.fmt(Math.round(s/Math.max(1,pc.left))))} ${t('per_day')} · ${t('income')} ${esc(PO.fmt(PO.incomeIn(p)+PO.expectedIncome(p)))} − bills ${esc(PO.fmt(PO.committed(p)))} − ${t('goals').toLowerCase()} ${esc(PO.fmt(PO.goalContribIn(p)))} − ${t('spent').toLowerCase()} ${esc(PO.fmt(spent))}</div><div class="track"><i style="width:${budgetable>0?Math.min(100,Math.round(spent/budgetable*100)):0}%"></i><b style="inset-inline-start:${Math.round(pc.share*100)}%" title="today"></b></div><div class="line">${warn?t('ahead'):t('on_pace')}.</div></div>
  ${alerts.length?`<div class="card"><div class="sec" style="margin-top:0">${t('alerts')} <button class="pill" data-go="alerts" style="float:inline-end">${t('settings')}</button></div>${alerts.slice(0,4).map(a=>`<div class="row" role="button" tabindex="0" data-go="${a.action==='cover'||a.action==='env'?'envelope':a.action==='recurring'?'recurring':a.action==='accounts'?'accounts':a.action==='alerts'?'alerts':'home'}" ${H.p(a.envId?{id:a.envId}:{})}><div style="min-width:0"><div class="t">${esc(a.title)}</div><div class="m">${esc(a.body||'')}</div></div><span class="pill ${a.level>=2?'over':'amb'}">${a.kind}</span></div>`).join('')}</div>`:''}
  ${review.length?`<button class="card" style="width:100%;text-align:start;display:flex;justify-content:space-between;align-items:center" data-go="review"><span><b>${review.length} ${t('to_review')}</b><div class="sub">Captured from ${esc([...new Set(review.map(r=>r.source))].join(', '))}</div></span><span class="pill acc">${t('review')}</span></button>`:''}
  <div class="sec">${t('today')} <button class="pill" data-go="transactions" style="float:inline-end">${t('all')}</button></div><div class="card list">${today.length?today.map(x=>H.txRow(x)).join(''):H.empty(t('nothing_yet'),'Tap + to add, or speak it with the mic.')}</div>
  <div class="grid2"><button class="tile" data-go="accounts"><div class="k">${t('net_worth')}</div><div class="v">${esc(PO.fmt(PO.netWorth()))}</div><div class="sub">${PO.list('accts').filter(a=>!a.archived).length} ${t('accounts').toLowerCase()}</div></button><button class="tile" data-go="recurring"><div class="k">Next bill</div>${(()=>{ const b=PO.upcomingBills(PO.periodFor(PO.addDays(PO.today(),60),{type:'monthly',day:1}))[0]||PO.upcomingBills(p)[0]; return b?`<div class="v">${esc(PO.fmt(PO.toBase(b.o.amt??b.r.amt,b.r.cur)))}</div><div class="sub">${esc(b.r.name)} · ${esc(PO.relDate(b.o.date))}</div>`:`<div class="v">—</div><div class="sub">Nothing scheduled</div>`; })()}</button></div>
  <div class="menu" style="margin-top:12px">${[['history',t('history')],['trash',t('trash')],['categories',t('categories')],['payees',t('payees')],['rules',t('rules')],['importer',t('import')],['debt','Debt planner'],['data',t('data')],['security',t('security')]].map(([k,l])=>`<button class="chip small" data-go="${k}">${esc(l)}</button>`).join('')}</div>`; } };
PO.ACT['toggle-hide'] = () => { PO.state.settings.hideAmounts=!PO.state.settings.hideAmounts; PO.save(); PO.render(); };
PO.ACT['cover'] = b => { const e=PO.get('envs',b.dataset.env); const p=PO.curPeriod(); const need=PO.envSpent(e,p)-PO.envLimit(e,p); const donors=PO.list('envs').filter(x=>x.id!==e.id&&!x.archived&&PO.envLimit(x,p)-PO.envSpent(x,p)>0).sort((a,c)=>(PO.envLimit(c,p)-PO.envSpent(c,p))-(PO.envLimit(a,p)-PO.envSpent(a,p))); $('#notif').hidden=true; if(!donors.length){ PO.toast('No envelope has unused money to move'); return; } PO.form({title:`${t('cover')} ${e.name}`, intro:`${e.name} is over by ${PO.fmt(Math.max(0,need),null,{force:true})}. Move limit from another envelope for this period only.`, values:{from:donors[0].id, amt:Math.min(Math.max(0,need), PO.envLimit(donors[0],p)-PO.envSpent(donors[0],p))}, fields:[{k:'from',label:'From',type:'select',options:donors.map(x=>({v:x.id,l:`${x.name} (${PO.fmt(PO.envLimit(x,p)-PO.envSpent(x,p),null,{force:true})} unused)`}))},{k:'amt',label:t('amount'),type:'money',required:true}], onSave:v=>{ const from=PO.get('envs',v.from); const gid=PO.group(()=>{ const fa=PO.envAlloc(from,p); PO.commit('alloc', fa?fa.id:PO.uid('al'), {envId:from.id, period:p.key, assigned:(fa?fa.assigned:from.limit)-v.amt},'move'); const ta=PO.envAlloc(e,p); PO.commit('alloc', ta?ta.id:PO.uid('al'), {envId:e.id, period:p.key, assigned:(ta?ta.assigned:e.limit)+v.amt},'move'); }); H.afterWrite(`Moved ${PO.fmt(v.amt,null,{force:true})} from ${from.name} to ${e.name}`, gid); } }); };

/* ---------- review queue */
PO.SCREENS.review = { render:()=>{ const items=PO.list('review'); return `${H.hdr(t('review'), 'Captured on this device from app notifications, share sheet and email. Nothing posts until you accept it.', `<button class="pill" data-act="review-share">Share-sheet intake</button>`, t('home'))}
  ${items.length?items.map(r=>`<div class="card"><div style="display:flex;justify-content:space-between;gap:8px"><div style="min-width:0"><b>${esc(r.payee||r.rawText)}</b><div class="sub">${esc(r.source)} · ${esc(PO.relDate(r.date))} ${esc(r.time||'')} · confidence ${Math.round((r.confidence||0.5)*100)}%</div><div class="sub" style="font-style:italic">${esc(r.rawText)}</div></div>${H.money((r.kind==='income'?1:-1)*r.amt, r.cur, {signed:true,plus:true})}</div>
    <div class="chips" style="margin-top:10px">${PO.list('cats').filter(c=>!c.parent&&c.kind===(r.kind==='income'?'income':'expense')&&!c.excluded).slice(0,5).map(c=>`<button class="chip small" data-act="review-cat" data-id="${r.id}" data-v="${c.id}" aria-pressed="${PO.catRoot(r.cat)===c.id}">${esc(c.name)}</button>`).join('')}</div>
    <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="btn sm" data-act="review-accept" data-id="${r.id}">${t('accept')} as ${esc(PO.catName(r.cat))}</button><button class="btn sm ghost" data-act="review-edit" data-id="${r.id}">Edit then accept</button><button class="btn sm ghost" data-act="review-ignore" data-id="${r.id}">${t('ignore')}</button><button class="chip small" data-act="review-ignore-source" data-id="${r.id}">Always ignore ${esc(r.source)}</button></div></div>`).join(''):H.empty('All caught up','New captures appear here within seconds of the notification.', `<button class="btn sm ghost" data-act="review-share">Try share-sheet intake</button>`)}
  <div class="card"><div class="row"><div><div class="t">Auto-post trusted sources</div><div class="m">${PO.state.settings.autoPost?'On':'Off'} · turns on per source after 10 consistent accepts</div></div><button class="sw" role="switch" aria-checked="${!!PO.state.settings.autoPost}" data-act="toggle-setting" data-k="autoPost" aria-label="Auto-post"></button></div><div class="row"><div><div class="t">Ignored sources</div><div class="m">${esc((PO.state.settings.ignoredSources||[]).join(', ')||'None')}</div></div>${(PO.state.settings.ignoredSources||[]).length?`<button class="pill" data-act="review-unignore">Clear</button>`:''}</div></div>`; } };
PO.ACT['review-cat'] = b => { PO.commit('review', b.dataset.id, {cat:b.dataset.v},'edit'); PO.render(); };
PO.ACT['review-accept'] = b => { const r=PO.get('review',b.dataset.id); const id=PO.uid('t'); const gid=PO.group(()=>{ PO.commit('tx',id,{kind:r.kind, amt:r.amt, cur:r.cur, acct:r.acct, cat:r.cat||'uncat', payeeId:PO.ensurePayee(r.payee), payee:r.payee, date:r.date, time:r.time, status:'cleared', source:r.source, note:'', tags:[], splits:[], attachments:[], rawText:r.rawText},'create'); PO.purge('review', r.id); }); PO.learn(r.payee, r.cat); H.afterWrite(`Posted to ${PO.catName(r.cat)}.`, gid); };
PO.ACT['review-edit'] = b => { const r=PO.get('review',b.dataset.id); PO.txForm({kind:r.kind, amt:r.amt, cur:r.cur, acct:r.acct, cat:r.cat, payee:r.payee, date:r.date, time:r.time, source:r.source}, {fromReview:true, onSaved:()=>{ PO.purge('review', r.id); }}); };
PO.ACT['review-ignore'] = b => { const r=PO.get('review',b.dataset.id); const gid=PO.group(()=>PO.remove('review',r.id,'ignore')); H.afterWrite('Ignored', gid); };
PO.ACT['review-ignore-source'] = b => { const r=PO.get('review',b.dataset.id); PO.state.settings.ignoredSources=[...new Set([...(PO.state.settings.ignoredSources||[]), r.source])]; const gid=PO.group(()=>PO.list('review').filter(x=>x.source===r.source).forEach(x=>PO.remove('review',x.id,'ignore'))); H.afterWrite(`${r.source} will be ignored`, gid); };
PO.ACT['review-unignore'] = () => { PO.state.settings.ignoredSources=[]; PO.save(); PO.render(); };
PO.ACT['review-share'] = () => { PO.form({title:'Share to Penny', intro:'Simulates sharing a payment message, a notification or a receipt text into the app. Try: "Paid ₹450 to Blue Tokai via UPI".', fields:[{k:'text',label:'Shared text',type:'textarea',required:true,placeholder:'Paid ₹450 to Blue Tokai via UPI'}], saveLabel:'Parse into review queue', onSave:v=>{ const p=PO.parseShareText(v.text); if(!p.amt){ PO.toast('No amount found in that text'); return false; } PO.commit('review',PO.uid('rv'),{rawText:v.text, amt:PO.toMinor(p.amt,PO.cur()), cur:PO.cur(), kind:p.kind, acct:PO.profile().defaultAcct||(PO.list('accts')[0]||{}).id, cat:PO.suggestCat(p.payee)||'uncat', payee:p.payee, source:'Share sheet', date:PO.today(), time:PO.nowHM(), confidence:0.55},'capture'); PO.go('review'); PO.toast('Added to review'); } }); };
PO.ACT['toggle-setting'] = b => { const k=b.dataset.k; PO.state.settings[k]=!PO.state.settings[k]; PO.save(); PO.render(); };

/* ---------- transactions: search, filters, saved searches, bulk, two-pane on tablet */
PO.SCREENS.transactions = { two:true, render:(pr)=>{ const q=(pr.q||'').toLowerCase(); const f={acct:pr.acct||'', cat:pr.cat||'', tag:pr.tag||'', status:pr.status||'', kind:pr.kind||'', from:pr.from||'', to:pr.to||'', min:pr.min?Number(pr.min):null, max:pr.max?Number(pr.max):null, att:pr.att==='1', uncat:pr.uncat==='1', person:pr.person||''};
  let list=PO.list('tx').filter(PO.visible); const nl = PO.parseNL(q); if(nl) Object.assign(f, nl.filters);
  list=list.filter(x=>{ if(nl&&nl.text){ const hay=`${PO.payeeName(x)} ${x.note||''} ${PO.catPath(x.cat)} ${(x.tags||[]).join(' ')} ${PO.acctName(x.acct)} ${PO.toMajor(x.amt,x.cur)}`.toLowerCase(); if(!hay.includes(nl.text)) return false; } else if(q && !nl){ const hay=`${PO.payeeName(x)} ${x.note||''} ${PO.catPath(x.cat)} ${(x.tags||[]).join(' ')} ${PO.acctName(x.acct)} ${PO.toMajor(x.amt,x.cur)}`.toLowerCase(); if(!hay.includes(q)) return false; }
    if(f.acct && x.acct!==f.acct && x.toAcct!==f.acct) return false; if(f.cat && !PO.catDesc(f.cat).includes(x.cat) && !(x.splits||[]).some(s=>PO.catDesc(f.cat).includes(s.cat))) return false; if(f.tag && !(x.tags||[]).includes(f.tag)) return false; if(f.status && x.status!==f.status) return false; if(f.kind && x.kind!==f.kind) return false; if(f.from && x.date<f.from) return false; if(f.to && x.date>f.to) return false; if(f.min!=null && PO.toBase(x.amt,x.cur)<f.min) return false; if(f.max!=null && PO.toBase(x.amt,x.cur)>f.max) return false; if(f.att && !(x.attachments||[]).length) return false; if(f.uncat && x.cat && x.cat!=='uncat' && x.kind!=='transfer') return false; return true; });
  const sort=pr.sort||'date'; list.sort((a,b)=> sort==='amount'?b.amt-a.amt : sort==='payee'?PO.payeeName(a).localeCompare(PO.payeeName(b)) : (b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
  const days=[...new Set(list.map(x=>x.date))]; const total=list.filter(x=>x.kind==='expense').reduce((s,x)=>s+PO.toBase(x.amt,x.cur),0); const sel=PO.ui.sel.size;
  const chip=(k,v,l,on)=>`<button class="chip small" aria-pressed="${on}" data-go="transactions" ${H.p({...pr, [k]: on?'':v})}>${esc(l)}</button>`;
  const left = `${H.hdr(t('search'), `${list.length} results · ${t('expense')} ${PO.fmt(total)}`, `<button class="pill" data-act="save-search" ${H.p(pr)}>Save search</button>`, t('home'))}
  <form data-search style="display:flex;gap:6px;margin-bottom:8px"><input id="txsearch" class="inp" placeholder="Search or ask: coffee last month over 200" value="${esc(pr.q||'')}" aria-label="${t('search')}"><button class="btn sm" type="submit">Go</button></form>
  ${nl?`<div class="sub" style="margin-bottom:6px">Understood as: ${esc(nl.explain)}</div>`:''}
  <div class="chips" style="margin-bottom:8px">${chip('kind','expense',t('expense'),f.kind==='expense')}${chip('kind','income',t('income'),f.kind==='income')}${chip('status','pending',t('pending'),f.status==='pending')}${chip('uncat','1',t('uncategorised'),f.uncat)}${chip('att','1','📎',f.att)}${PO.list('accts').filter(a=>!a.archived).slice(0,3).map(a=>chip('acct',a.id,a.name,f.acct===a.id)).join('')}<button class="chip small" data-act="filter-more" ${H.p(pr)}>${t('filters')}…</button><button class="chip small" data-act="sort" ${H.p(pr)}>Sort: ${esc(sort)}</button></div>
  ${PO.list('saved').length?`<div class="chips" style="margin-bottom:8px">${PO.list('saved').map(s=>`<button class="chip small" data-go="transactions" ${H.p(s.params||{q:s.q||'',tag:(s.tags||[])[0]||''})}>★ ${esc(s.name)}</button>`).join('')}</div>`:''}
  ${sel?`<div class="card" style="background:var(--accent-soft)"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px"><b>${sel} selected</b><div class="menu"><button class="chip small" data-act="bulk" data-k="cat">${t('category')}</button><button class="chip small" data-act="bulk" data-k="acct">${t('account')}</button><button class="chip small" data-act="bulk" data-k="tag">Tag</button><button class="chip small" data-act="bulk" data-k="date">Date</button><button class="chip small" data-act="bulk" data-k="merge">Merge dupes</button><button class="chip small" data-act="bulk" data-k="delete">${t('delete')}</button><button class="chip small" data-act="sel-clear">Clear</button></div></div></div>`:''}
  ${list.length? days.map(d=>`<div class="sec">${esc(PO.relDate(d))}</div><div class="card list">${list.filter(x=>x.date===d).map(x=>H.txRow(x,{select:true})).join('')}</div>`).join('') : (q||Object.values(f).some(Boolean)) ? H.empty('No matches', `Nothing matches "${pr.q||'these filters'}". Try fewer filters or a different spelling.`, `<button class="btn sm ghost" data-go="transactions">Clear filters</button>`) : H.empty(t('nothing_yet'),'Add a transaction or import a statement.',`<button class="btn sm" data-go="importer">${t('import')}</button>`)}`;
  if(!PO.ui.tablet) return left; const first=list[0]; return `<div>${left}</div><div>${first?`<div class="card"><b>Details</b><div class="sub">Tablet two-pane: the first result is shown here; tap any row to edit.</div><div class="row"><div class="t">${esc(PO.payeeName(first)||PO.catName(first.cat))}</div>${H.money(first.amt,first.cur)}</div><div class="row"><div class="t">${t('category')}</div><div>${esc(PO.catPath(first.cat))}</div></div><div class="row"><div class="t">${t('account')}</div><div>${esc(PO.acctName(first.acct))}</div></div><div class="row"><div class="t">${t('date')}</div><div>${esc(first.date)} ${esc(first.time||'')}</div></div><div class="row"><div class="t">${t('status')}</div><div>${esc(first.status||'')}</div></div><div class="row"><div class="t">Source</div><div>${esc(first.source||'manual')}</div></div><button class="btn sm" data-act="tx-open" data-id="${first.id}" style="margin-top:8px">${t('edit')}</button></div>`:H.empty('No selection','')}</div>`; },
  after:()=>{ const f=document.querySelector('form[data-search]'); if(f) f.addEventListener('submit', ev=>{ ev.preventDefault(); PO.go('transactions', {...PO.ui.params, q:$('#txsearch').value}); }); } };
PO.parseNL = q => { if(!q||!/\b(last|this|over|under|above|below|between|yesterday|today|week|month|period|kinsenas|cash|card)\b/.test(q)) return null; const f={}; const parts=[]; let text=q; const p=PO.curPeriod();
  if(/\blast (month|period|kinsenas|payday)\b/.test(q)){ const lp=PO.shiftPeriod(p,-1,PO.cycle(),PO.ctx()); f.from=lp.start; f.to=lp.end; parts.push(`last period (${PO.periodLabel(lp)})`); text=text.replace(/\blast (month|period|kinsenas|payday)\b/,''); }
  else if(/\bthis (month|period|kinsenas)\b/.test(q)){ f.from=p.start; f.to=p.end; parts.push('this period'); text=text.replace(/\bthis (month|period|kinsenas)\b/,''); }
  else if(/\blast week\b/.test(q)){ f.from=PO.addDays(PO.today(),-13); f.to=PO.addDays(PO.today(),-7); parts.push('last week'); text=text.replace(/\blast week\b/,''); }
  else if(/\bthis week\b/.test(q)){ f.from=PO.addDays(PO.today(),-6); f.to=PO.today(); parts.push('this week'); text=text.replace(/\bthis week\b/,''); }
  else if(/\byesterday\b/.test(q)){ f.from=f.to=PO.addDays(PO.today(),-1); parts.push('yesterday'); text=text.replace(/\byesterday\b/,''); }
  else if(/\btoday\b/.test(q)){ f.from=f.to=PO.today(); parts.push('today'); text=text.replace(/\btoday\b/,''); }
  let m; if((m=q.match(/\b(over|above|more than)\s+(\d+)/))){ f.min=PO.toMinor(m[2],PO.cur()); parts.push(`over ${m[2]}`); text=text.replace(m[0],''); } if((m=q.match(/\b(under|below|less than)\s+(\d+)/))){ f.max=PO.toMinor(m[2],PO.cur()); parts.push(`under ${m[2]}`); text=text.replace(m[0],''); } if((m=q.match(/\bbetween\s+(\d+)\s+and\s+(\d+)/))){ f.min=PO.toMinor(m[1],PO.cur()); f.max=PO.toMinor(m[2],PO.cur()); parts.push(`between ${m[1]} and ${m[2]}`); text=text.replace(m[0],''); }
  const cashA=PO.list('accts').find(a=>a.type==='cash'); if(/\bcash\b/.test(q)&&cashA){ f.acct=cashA.id; parts.push('cash account'); text=text.replace(/\bcash\b/,''); } const cardA=PO.list('accts').find(a=>a.type==='card'); if(/\bcard\b/.test(q)&&cardA){ f.acct=cardA.id; parts.push('card'); text=text.replace(/\bcard\b/,''); }
  text=text.replace(/\b(in|on|at|for|spent|spend|show|me|all|transactions|the)\b/g,' ').replace(/\s+/g,' ').trim(); const cat=text?PO.list('cats').find(c=>c.name.toLowerCase()===text||c.name.toLowerCase().startsWith(text)):null; if(cat){ f.cat=cat.id; parts.push(`category ${cat.name}`); text=''; } if(text) parts.unshift(`text "${text}"`); return {filters:f, text, explain:parts.join(', ')}; };
PO.ACT['filter-more'] = b => { const pr=JSON.parse(b.dataset.p||'{}'); PO.form({title:t('filters'), values:{...pr}, fields:[{k:'from',label:t('from'),type:'date'},{k:'to',label:t('to'),type:'date'},{k:'acct',label:t('account'),type:'select',options:[{v:'',l:t('all')},...H.acctOptions()]},{k:'cat',label:t('category'),type:'select',options:[{v:'',l:t('all')},...H.catOptions('expense'),...H.catOptions('income')]},{k:'tag',label:'Tag',type:'select',options:[{v:'',l:t('all')},...PO.list('tags').map(x=>({v:x.name,l:x.name}))]},{k:'kind',label:'Type',type:'select',options:[{v:'',l:t('all')},{v:'expense',l:t('expense')},{v:'income',l:t('income')},{v:'transfer',l:t('transfer')},{v:'refund',l:t('refund')},{v:'adjustment',l:t('adjustment')}]},{k:'status',label:t('status'),type:'select',options:[{v:'',l:t('all')},{v:'pending',l:t('pending')},{v:'cleared',l:t('cleared')},{v:'reconciled',l:t('reconciled')}]},{k:'min',label:'Min amount',type:'money'},{k:'max',label:'Max amount',type:'money'}], saveLabel:'Apply', onSave:v=>{ const o={...pr}; ['from','to','acct','cat','tag','kind','status'].forEach(k=>{ if(v[k]) o[k]=v[k]; else delete o[k]; }); if(v.min!=null) o.min=v.min; else delete o.min; if(v.max!=null) o.max=v.max; else delete o.max; PO.go('transactions', o); } }); };
PO.ACT['sort'] = b => { const pr=JSON.parse(b.dataset.p||'{}'); const next={date:'amount',amount:'payee',payee:'date'}[pr.sort||'date']; PO.go('transactions',{...pr, sort:next}); };
PO.ACT['save-search'] = b => { const pr=JSON.parse(b.dataset.p||'{}'); PO.form({title:'Save this search', fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true}], onSave:v=>{ PO.commit('saved',PO.uid('sv'),{name:v.name, params:pr}); PO.render(); PO.toast('Saved'); } }); };

/* ---------- budgets */
PO.SCREENS.budgets = { render:(pr)=>{ const p=H.periodFromParams(pr); const envs=PO.list('envs').filter(e=>!e.archived); const inc=PO.incomeIn(p), assigned=PO.assignedIn(p), avail=PO.availableToAssign(p); const spent=PO.spentTotal(p); const lim=envs.reduce((s,e)=>s+PO.envLimit(e,p),0); const pk=PO.pack();
  return `${H.hdr(t('budgets'), '', `<div style="display:flex;gap:6px"><button class="pill" data-go="goals">${t('goals')}</button><button class="pill acc" data-act="env-add">+ ${t('envelopes').slice(0,-1)}</button></div>`)}${H.periodNav(p,'budgets')}
  <div class="card"><div style="display:flex;justify-content:space-between;align-items:baseline"><b>${t('available')}</b><span class="amt ${avail<0?'':'in'}" style="color:${avail<0?'var(--over)':''}">${esc(PO.fmt(avail))}</span></div><div class="sub">${t('income')} ${esc(PO.fmt(inc))} − ${t('assigned').toLowerCase()} ${esc(PO.fmt(assigned))} − ${t('goals').toLowerCase()} ${esc(PO.fmt(PO.goalContribIn(p)))}</div><div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap"><button class="chip small" data-act="assign-last" ${H.p({period:p.start})}>Same as last period</button><button class="chip small" data-act="assign-under" ${H.p({period:p.start})}>Fund underfunded first</button><button class="chip small" data-act="cycle-edit">${esc(PO.cycleName(PO.cycle()))}</button></div></div>
  <div class="card"><div style="display:flex;justify-content:space-between;align-items:baseline"><b>${t('envelopes')}</b><span class="sub">${esc(PO.fmt(spent))} of ${esc(PO.fmt(lim))}</span></div>${H.bar(spent,lim)}</div>
  <div class="card">${envs.length?envs.map(e=>{ const ep=PO.envPeriod(e,p); const sp=PO.envSpent(e,ep), l=PO.envLimit(e,ep), carry=PO.envCarry(e,ep); return `<div class="env" role="button" tabindex="0" data-go="envelope" ${H.p({id:e.id, period:p.start})}><div class="top2"><span class="nm">${esc(e.name)} ${e.rollover&&e.rollover!=='none'?`<span class="pill">${t('rollover')}${carry?` ${PO.fmt(carry,null,{force:true,plus:true})}`:''}</span>`:''}${e.periodRule?`<span class="pill">${esc(PO.cycleName(e.periodRule))}</span>`:''}${e.alerts==='off'?'<span class="pill">🔕</span>':''}</span><span class="nums">${esc(PO.fmt(sp))} / ${esc(PO.fmt(l))}</span></div>${H.bar(sp,l)}</div>`; }).join(''):H.empty('No envelopes yet','Create one per category you want to cap.',`<button class="btn sm" data-act="env-add">Add envelope</button>`)}</div>
  <div class="sec">Templates</div><div class="chips">${pk.festivals.map(f=>`<button class="chip small" data-act="pot-template" data-v="${esc(f.n)}" data-m="${f.m}">${esc(f.n)} pot</button>`).join('')}<button class="chip small" data-act="tmpl-apply" data-v="salaried">Salaried starter</button><button class="chip small" data-act="tmpl-apply" data-v="gig">Gig worker</button><button class="chip small" data-act="tmpl-apply" data-v="household">Household</button></div>
  <div class="sec">Archived</div><div class="chips">${PO.list('envs').filter(e=>e.archived).map(e=>`<button class="chip small" data-act="env-unarchive" data-id="${e.id}">↩ ${esc(e.name)}</button>`).join('')||'<span class="sub">None</span>'}</div>`; } };
PO.envForm = (e={}) => { const isNew=!e.id; PO.form({title:isNew?'New envelope':`${t('edit')} ${e.name}`, values:{name:e.name||'', cat:e.cat||'', limit:e.limit??null, rollover:e.rollover||'none', cap:e.cap??null, alerts:e.alerts||'all', own:e.periodRule?e.periodRule.type:'', scope:(e.scope||[]).join(',')}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'cat',label:'Main category',type:'select',options:H.catOptions('expense'),required:true,hint:'Includes its subcategories'},{k:'scope',label:'Extra categories (ids, comma separated)',type:'text',hint:'Advanced: add more categories to this envelope'},{k:'limit',label:'Limit per period',type:'money',required:true},{k:'rollover',label:t('rollover'),type:'chips',options:[{v:'none',l:'None'},{v:'positive',l:'Carry unspent'},{v:'both',l:'Carry unspent and overspend'}]},{k:'cap',label:'Rollover cap (optional)',type:'money'},{k:'alerts',label:t('alerts'),type:'chips',options:[{v:'all',l:'Near and over par'},{v:'near',l:'Near only'},{v:'off',l:'Off'}]},{k:'own',label:'Own period',type:'select',options:[{v:'',l:'Follows the budget cycle'},{v:'monthly',l:'Monthly'},{v:'quarterly',l:'Quarterly'},{v:'yearly',l:'Yearly'}]}], onSave:v=>{ const patch={name:v.name, cat:v.cat, scope:v.scope?v.scope.split(',').map(s=>s.trim()).filter(Boolean):[], limit:v.limit, rollover:v.rollover, cap:v.cap, alerts:v.alerts, periodRule:v.own?{type:v.own, fiscal:PO.profile().fiscal, day:1}:null}; const gid=PO.group(()=>PO.commit('envs', e.id||PO.uid('e'), patch)); H.afterWrite(isNew?'Envelope added':'Saved', gid); }, onDelete:isNew?null:()=>{ PO.confirmSheet(`${t('delete')} ${e.name}?`, 'Transactions keep their categories. The envelope goes to Trash for 30 days; archive instead to keep its history visible.', ()=>{ const gid=PO.group(()=>PO.remove('envs',e.id)); PO.go('budgets'); PO.toast('Deleted', gid); }); }, actions:isNew?[]:[{k:'arch',label:e.archived?'Unarchive':t('archive'),run:()=>{ PO.commit('envs',e.id,{archived:!e.archived},'archive'); PO.go('budgets'); PO.toast(e.archived?'Restored':'Archived'); return 'close'; }}] }); };
PO.ACT['env-add'] = () => PO.envForm();
PO.ACT['env-edit'] = b => PO.envForm(PO.get('envs',b.dataset.id));
PO.ACT['env-unarchive'] = b => { PO.commit('envs',b.dataset.id,{archived:false},'archive'); PO.render(); };
PO.ACT['assign-last'] = b => { const p=PO.periodOf(JSON.parse(b.dataset.p).period); const prev=PO.shiftPeriod(p,-1,PO.cycle(),PO.ctx()); const gid=PO.group(()=>PO.list('envs').filter(e=>!e.archived).forEach(e=>{ const pa=PO.envAlloc(e,prev); const a=PO.envAlloc(e,p); PO.commit('alloc', a?a.id:PO.uid('al'), {envId:e.id, period:p.key, assigned: pa?pa.assigned:e.limit},'assign'); })); H.afterWrite('Assigned like last period', gid); };
PO.ACT['assign-under'] = b => { const p=PO.periodOf(JSON.parse(b.dataset.p).period); let avail=PO.availableToAssign(p); if(avail<=0){ PO.toast('Nothing left to assign'); return; } const gid=PO.group(()=>PO.list('envs').filter(e=>!e.archived).sort((a,c)=>(PO.envSpent(c,p)-PO.envLimit(c,p))-(PO.envSpent(a,p)-PO.envLimit(a,p))).forEach(e=>{ const gap=PO.envSpent(e,p)-PO.envLimit(e,p); if(gap>0&&avail>0){ const add=Math.min(gap,avail); avail-=add; const a=PO.envAlloc(e,p); PO.commit('alloc', a?a.id:PO.uid('al'), {envId:e.id, period:p.key, assigned:(a?a.assigned:e.limit)+add},'assign'); } })); H.afterWrite('Underfunded envelopes topped up', gid); };
PO.ACT['cycle-edit'] = () => { const c=PO.cycle(); PO.form({title:t('pay_cycle'), intro:'Changing the cycle re-attributes every transaction to its new period. Nothing is lost.', values:{type:c.type, day:c.day||1, a:(c.days||[15,'last'])[0], b:(c.days||[15,'last'])[1], weekday:c.weekday??1, anchor:c.anchor||PO.today(), threshold:c.threshold||0}, fields:[{k:'type',label:'Cycle',type:'select',options:[['monthly','Monthly'],['semimonthly','Twice a month'],['weekly','Weekly'],['biweekly','Every two weeks'],['fourweekly','Every four weeks'],['quarterly','Quarterly'],['yearly','Yearly'],['onincome','When money lands']].map(([v,l])=>({v,l}))},{k:'day',label:'Start day of month',type:'number',min:1,max:31},{k:'a',label:'First day (twice a month)',type:'number',min:1,max:31},{k:'b',label:'Second day (number or "last")',type:'text'},{k:'weekday',label:'Week starts (0 Sunday … 6 Saturday)',type:'number',min:0,max:6},{k:'anchor',label:'Anchor payday (two or four weekly)',type:'date'},{k:'threshold',label:'"Money landed" threshold',type:'money'}], onSave:v=>{ const r={type:v.type}; if(v.type==='monthly') r.day=v.day||1; if(v.type==='semimonthly') r.days=[v.a||15, v.b==='last'?'last':(Number(v.b)||'last')]; if(v.type==='weekly') r.weekday=v.weekday??1; if(v.type==='biweekly'||v.type==='fourweekly') r.anchor=v.anchor; if(v.type==='quarterly'||v.type==='yearly') r.fiscal=PO.profile().fiscal; if(v.type==='onincome') r.threshold=v.threshold||0; const before=PO.spentTotal(PO.curPeriod()); PO.profile().cycle=r; PO.save(); const after=PO.spentTotal(PO.curPeriod()); PO.go('budgets'); PO.toast(`Cycle changed. This period's spend ${PO.fmt(before,null,{force:true})} → ${PO.fmt(after,null,{force:true})}`); } }); };
PO.ACT['pot-template'] = b => { const name=b.dataset.v, m=Number(b.dataset.m); const y=new Date().getFullYear()+(m<new Date().getMonth()+1?1:0); const due=PO.mk(y,m,1); const lastYear=PO.list('tx').filter(x=>x.kind==='expense'&&x.date>=PO.mk(y-1,m,1)&&x.date<=PO.mk(y-1,m,31)).reduce((s,x)=>s+PO.toBase(x.amt,x.cur),0); const target = lastYear || PO.toMinor(15000*(PO.RATES[PO.cur()]/84),PO.cur()); const periods=Math.max(1, Math.round(PO.daysBetween(PO.today(),due)/PO.curPeriod().days)); PO.form({title:`${name} pot`, intro:lastYear?`Last year you spent ${PO.fmt(lastYear,null,{force:true})} in that window.`:'No spend from last year in that window; a typical amount is prefilled.', values:{name:`${name} ${y}`, target, due, per:Math.ceil(target/periods)}, fields:[{k:'name',label:'Name',type:'text',required:true},{k:'target',label:'Target',type:'money',required:true},{k:'due',label:'Needed by',type:'date'},{k:'per',label:'Save per period',type:'money'}], onSave:v=>{ const gid=PO.group(()=>PO.commit('goals',PO.uid('g'),{name:v.name,target:v.target,saved:0,perPeriod:v.per,due:v.due,status:'active',kind:'pot'})); H.afterWrite('Pot created', gid); } }); };
PO.ACT['tmpl-apply'] = b => { const k=b.dataset.v; const pid=PO.state.currentProfile; const base = {salaried:[['Food','food',9000],['Transport','trans',2500],['Utilities','util',4500],['Eating out','eat',3000],['Shopping','shop',4000],['Fun','fun',2000]], gig:[['Food','food',6000],['Fuel and transport','trans',4000],['Phone and data','util.mobile',800],['Tools and repairs','shop',2500],['Family','fam',5000],['Buffer','fin',3000]], household:[['Groceries','food',14000],['Rent and bills','home',20000],['School','fam.school',6000],['Health','health',3000],['Gifts','gift',3000],['Fun','fun',2500]]}[k]; const scale=PO.RATES[PO.cur()]/84; const gid=PO.group(()=>base.forEach(([n,c,l])=>{ if(!PO.list('envs').find(e=>e.name===n)) PO.commit('envs',PO.uid('e'),{name:n,cat:PO.cid(pid,c),limit:PO.toMinor(Math.round(l*scale),PO.cur()),rollover:'none',alerts:'all'}); })); H.afterWrite(`${k} template applied`, gid); };

/* ---------- envelope detail */
PO.SCREENS.envelope = { render:(pr)=>{ const e=PO.get('envs',pr.id); if(!e) return H.err('Envelope not found','It may have been deleted.',`<button class="btn sm ghost" data-go="trash">${t('trash')}</button>`); const p=PO.envPeriod(e,H.periodFromParams(pr)); const sp=PO.envSpent(e,p), l=PO.envLimit(e,p), carry=PO.envCarry(e,p); const sc=PO.envScope(e); const rows=PO.spendRows(p).filter(r=>sc.has(r.cat)); const txs=[...new Set(rows.map(r=>r.tx))].sort((a,b)=>b.date.localeCompare(a.date)); const hist=[]; let q=p; for(let i=0;i<6;i++){ hist.unshift({p:q, sp:PO.envSpent(e,q), l:PO.envLimit(e,q)}); q=PO.shiftPeriod(q,-1,PO.cycle(),PO.ctx()); } const alloc=PO.envAlloc(e,p);
  return `${H.hdr(e.name, PO.periodLabel(p), `<button class="pill" data-act="env-edit" data-id="${e.id}">${t('edit')}</button>`, t('budgets'))}${H.periodNav(p,'envelope',{id:e.id})}
  <div class="card"><div class="amtbox" style="text-align:start;padding:0;font-size:28px">${esc(PO.fmt(l-sp))} <span style="font-size:14px">${t('left')} of ${esc(PO.fmt(l))}</span></div>${H.bar(sp,l)}<div class="sub" style="margin-top:6px">${alloc?`Assigned this period ${PO.fmt(alloc.assigned)} (default ${PO.fmt(e.limit)})`:`Default limit ${PO.fmt(e.limit)}`}${carry?` · carried ${PO.fmt(carry,null,{plus:true})}`:''} · ${t('alerts')}: ${e.alerts||'all'}</div><div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap"><button class="chip small" data-act="env-assign" data-id="${e.id}" data-period="${p.key}">Set this period's limit</button><button class="chip small" data-act="env-move" data-id="${e.id}" data-period="${p.key}">Move money</button><button class="chip small" data-act="env-watch" data-id="${e.id}">Add watch</button></div></div>
  <div class="sec">Last six periods, share of limit</div><div class="card"><svg viewBox="0 0 320 96" width="100%" height="96" role="img" aria-label="Share of limit used in the last six periods"><line x1="0" y1="72" x2="320" y2="72" stroke="var(--line)"/>${hist.map((h,i)=>{ const r=h.l>0?h.sp/h.l:(h.sp>0?1.2:0); const hh=Math.min(r,1.3)*52; return `<rect x="${i*52+14}" y="${72-hh}" width="28" height="${hh}" rx="3" fill="${i===5?'var(--accent)':r>=1?'var(--over)':'var(--bar-muted)'}"><title>${esc(PO.periodLabel(h.p))}: ${Math.round(r*100)}%</title></rect><text x="${i*52+28}" y="86" text-anchor="middle" font-size="10" fill="var(--muted)">${i===5?'now':'-'+(5-i)}</text>`; }).join('')}<line x1="0" y1="20" x2="320" y2="20" stroke="var(--muted)" stroke-dasharray="3 3"/><text x="316" y="16" text-anchor="end" font-size="10" fill="var(--muted)">limit</text></svg></div>
  <div class="sec">${t('this_period')} · ${txs.length}</div><div class="card list">${txs.length?txs.map(x=>H.txRow(x,{showDate:true})).join(''):H.empty('No spending yet','Transactions in this envelope\'s categories appear here.')}</div>`; } };
PO.ACT['env-assign'] = b => { const e=PO.get('envs',b.dataset.id); const p=PO.periodOf(b.dataset.period); const a=PO.envAlloc(e,p); PO.form({title:`Limit for ${PO.periodLabel(p)}`, values:{amt:a?a.assigned:e.limit, def:false}, fields:[{k:'amt',label:'Limit this period',type:'money',required:true},{k:'def',label:'Also make this the default for future periods',type:'toggle'}], onSave:v=>{ const gid=PO.group(()=>{ PO.commit('alloc', a?a.id:PO.uid('al'), {envId:e.id, period:p.key, assigned:v.amt},'assign'); if(v.def) PO.commit('envs',e.id,{limit:v.amt},'edit'); }); H.afterWrite('Limit updated', gid); } }); };
PO.ACT['env-move'] = b => { PO.ACT['cover']({dataset:{env:b.dataset.id}}); };
PO.ACT['env-watch'] = b => { const e=PO.get('envs',b.dataset.id); PO.commit('watch',PO.uid('w'),{name:e.name, cat:e.cat, limit:Math.round(PO.envLimit(e,PO.curPeriod())*0.5)}); PO.toast('Watch added at 50% of the limit; edit it under Alerts'); PO.render(); };

/* ---------- goals */
PO.SCREENS.goals = { render:()=>{ const gs=PO.list('goals'); return `${H.hdr(t('goals'), 'Sinking funds and pots that fill on your pay cycle', `<button class="pill acc" data-act="goal-add">+ Goal</button>`, t('budgets'))}
  ${gs.length?gs.map(g=>{ const p=g.target>0?Math.min(1,g.saved/g.target):0; const r=20, c=2*Math.PI*r; const periodsLeft=g.due?Math.max(0,Math.ceil(PO.daysBetween(PO.today(),g.due)/PO.curPeriod().days)):null; const need=periodsLeft?Math.ceil(Math.max(0,g.target-g.saved)/Math.max(1,periodsLeft)):null; return `<div class="card"><div style="display:flex;gap:14px;align-items:center"><svg width="48" height="48" viewBox="0 0 48 48" role="img" aria-label="${Math.round(p*100)}% saved"><circle cx="24" cy="24" r="${r}" fill="none" stroke="var(--sunk)" stroke-width="6"/><circle cx="24" cy="24" r="${r}" fill="none" stroke="${g.status==='done'?'var(--good)':'var(--accent)'}" stroke-width="6" stroke-dasharray="${c*p} ${c}" transform="rotate(-90 24 24)" stroke-linecap="round"/></svg><div style="flex:1;min-width:0"><b>${esc(g.name)}</b> ${g.status!=='active'?`<span class="pill">${esc(g.status)}</span>`:''}<div class="sub">${esc(PO.fmt(g.saved))} of ${esc(PO.fmt(g.target))}${g.due?` · by ${esc(PO.fmtDate(g.due,{day:'numeric',month:'short',year:'numeric'}))}`:''}</div><div class="sub">${g.perPeriod?`${PO.fmt(g.perPeriod)} per period`:''}${need!=null?` · ${need<=(g.perPeriod||0)?'on track':`behind, needs ${PO.fmt(need)} per period`}`:''}</div></div><span class="pill ${g.status==='done'?'good':'acc'}">${Math.round(p*100)}%</span></div><div class="menu" style="margin-top:10px"><button class="chip small" data-act="goal-contrib" data-id="${g.id}">Contribute</button><button class="chip small" data-act="goal-withdraw" data-id="${g.id}">Withdraw</button><button class="chip small" data-act="goal-pause" data-id="${g.id}">${g.status==='paused'?'Resume':'Pause'}</button><button class="chip small" data-act="goal-done" data-id="${g.id}">${g.status==='done'?'Reopen':'Complete'}</button><button class="chip small" data-act="goal-edit" data-id="${g.id}">${t('edit')}</button></div></div>`; }).join(''):H.empty('No goals yet','A goal is money set aside on a schedule. Festival pots live here too.',`<button class="btn sm" data-act="goal-add">Add goal</button>`)}`; } };
PO.goalForm = (g={}) => { const isNew=!g.id; PO.form({title:isNew?'New goal':g.name, values:{name:g.name||'', target:g.target??null, saved:g.saved??0, per:g.perPeriod??null, due:g.due||'', acct:g.acct||''}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'target',label:'Target',type:'money',required:true},{k:'saved',label:'Saved so far',type:'money'},{k:'per',label:'Auto-save per period',type:'money',hint:`Deducted from safe-to-spend each ${PO.cycleName(PO.cycle()).toLowerCase()}`},{k:'due',label:'Needed by',type:'date'},{k:'acct',label:'Linked account',type:'select',options:[{v:'',l:'None'},...H.acctOptions()]}], onSave:v=>{ const gid=PO.group(()=>PO.commit('goals', g.id||PO.uid('g'), {name:v.name,target:v.target,saved:v.saved||0,perPeriod:v.per||0,due:v.due||null,acct:v.acct||null,status:g.status||'active'})); H.afterWrite('Saved', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('goals',g.id)); H.afterWrite('Deleted. Balance returns to available.', gid); } }); };
PO.ACT['goal-add'] = () => PO.goalForm();
PO.ACT['goal-edit'] = b => PO.goalForm(PO.get('goals',b.dataset.id));
PO.ACT['goal-contrib'] = b => { const g=PO.get('goals',b.dataset.id); PO.form({title:`Contribute to ${g.name}`, values:{amt:g.perPeriod||null, acct:g.acct||PO.profile().defaultAcct}, fields:[{k:'amt',label:t('amount'),type:'money',required:true,autofocus:true},{k:'acct',label:'From account',type:'select',options:H.acctOptions()}], onSave:v=>{ const gid=PO.group(()=>{ PO.commit('goals',g.id,{saved:g.saved+v.amt},'contribute'); PO.commit('tx',PO.uid('t'),{kind:'expense',amt:v.amt,cur:PO.cur(),acct:v.acct,cat:PO.cid(PO.state.currentProfile,'save'),payee:g.name,payeeId:PO.ensurePayee(g.name),date:PO.today(),status:'cleared',source:'goal',goalId:g.id,excludeBudget:false,tags:[],splits:[],attachments:[]},'create'); }); H.afterWrite(`Added ${PO.fmt(v.amt,null,{force:true})} to ${g.name}`, gid); } }); };
PO.ACT['goal-withdraw'] = b => { const g=PO.get('goals',b.dataset.id); PO.form({title:`Withdraw from ${g.name}`, values:{amt:null, acct:g.acct||PO.profile().defaultAcct}, fields:[{k:'amt',label:t('amount'),type:'money',required:true,autofocus:true},{k:'acct',label:'To account',type:'select',options:H.acctOptions()}], validate:v=>v.amt>g.saved?{amt:`Only ${PO.fmt(g.saved,null,{force:true})} saved`}:null, onSave:v=>{ const gid=PO.group(()=>{ PO.commit('goals',g.id,{saved:g.saved-v.amt},'withdraw'); PO.commit('tx',PO.uid('t'),{kind:'refund',amt:v.amt,cur:PO.cur(),acct:v.acct,cat:PO.cid(PO.state.currentProfile,'save'),payee:g.name,payeeId:PO.ensurePayee(g.name),date:PO.today(),status:'cleared',source:'goal',goalId:g.id,tags:[],splits:[],attachments:[]},'create'); }); H.afterWrite(`Withdrew ${PO.fmt(v.amt,null,{force:true})}`, gid); } }); };
PO.ACT['goal-pause'] = b => { const g=PO.get('goals',b.dataset.id); const gid=PO.group(()=>PO.commit('goals',g.id,{status:g.status==='paused'?'active':'paused'},'status')); H.afterWrite(g.status==='paused'?'Resumed':'Paused', gid); };
PO.ACT['goal-done'] = b => { const g=PO.get('goals',b.dataset.id); const gid=PO.group(()=>PO.commit('goals',g.id,{status:g.status==='done'?'active':'done'},'status')); H.afterWrite(g.status==='done'?'Reopened':'Completed. Well done.', gid); };

/* ---------- accounts */
PO.SCREENS.accounts = { two:true, render:(pr)=>{ const accts=PO.list('accts'); const live=accts.filter(a=>!a.archived); const groups={}; live.forEach(a=>{ (groups[a.type]=groups[a.type]||[]).push(a); }); const TYPE={cash:'Cash',bank:'Bank',wallet:'E-wallets',card:'Credit cards',prepaid:'Prepaid',loan:'Loans',receivable:'Receivables',investment:'Investments',asset:'Assets',liability:'Liabilities',other:'Other'}; const links=PO.list('links');
  const left=`${H.hdr(t('accounts'), `${t('net_worth')} ${PO.fmt(PO.netWorth())}`, `<button class="pill acc" data-act="acct-add">+ ${t('account')}</button>`, t('home'))}
  ${Object.entries(groups).map(([type,list])=>`<div class="sec">${esc(TYPE[type]||type)}</div><div class="card list">${list.map(a=>{ const bal=PO.balance(a.id); const extra = a.type==='card' ? PO.cardInfo(a) : a.type==='cash' ? 'Tap to count and reconcile' : a.passThrough ? `Pays from ${PO.acctName(a.passThrough)}` : a.type==='loan' ? PO.loanInfo(a) : ''; const link=links.find(l=>(l.accts||[]).includes(a.id)); return `<div class="row" role="button" tabindex="0" data-go="account" ${H.p({id:a.id})}><div style="min-width:0"><div class="t">${esc(a.name)} ${a.includeNW===false?'<span class="pill">excluded</span>':''} ${link?`<span class="pill ${link.status==='ok'?'good':'danger'}">${esc(link.provider)}</span>`:''}</div><div class="m">${esc(extra||a.cur)}</div></div>${H.money(bal,a.cur)}</div>`; }).join('')}</div>`).join('')}
  ${accts.filter(a=>a.archived).length?`<div class="sec">Archived</div><div class="chips">${accts.filter(a=>a.archived).map(a=>`<button class="chip small" data-act="acct-unarchive" data-id="${a.id}">↩ ${esc(a.name)}</button>`).join('')}</div>`:''}
  <div class="sec">Bank sync</div><div class="card">${links.length?links.map(l=>`<div class="row"><div><div class="t">${esc(l.institution)}</div><div class="m">${esc(l.provider)} · last fetch ${esc(PO.relDate(l.lastFetch))} · consent until ${esc(PO.fmtDate(l.consentExpiry))} ${l.status!=='ok'?`· <span style="color:var(--danger)">${esc(l.error||'error')}</span>`:''}</div></div><div class="menu"><button class="chip small" data-act="link-fetch" data-id="${l.id}">Fetch</button><button class="chip small" data-act="link-reconsent" data-id="${l.id}">Re-consent</button><button class="chip small" data-act="link-disconnect" data-id="${l.id}">Disconnect</button></div></div>`).join(''):'<div class="sub">No linked banks.</div>'}<div class="row"><div><div class="t">Link a bank</div><div class="m">${esc(PO.pack().id==='IN'?'Account Aggregator with your consent':PO.pack().id==='PH'?'BSP Open Finance partner banks':'Open banking provider for your region')} · Plus covers the per-fetch fee</div></div><button class="btn sm" data-act="link-add">Link</button></div></div>`;
  if(!PO.ui.tablet) return left; const a=pr.id?PO.get('accts',pr.id):live[0]; return `<div>${left}</div><div>${a?PO.SCREENS.account.render({id:a.id, embedded:true}):''}</div>`; } };
PO.cardInfo = a => { const bal=-PO.balance(a.id); const d=Number(PO.today().slice(8)); const dueIn=((a.dueDay||1)-d+31)%31; const stmtIn=((a.stmtDay||1)-d+31)%31; const stmt=PO.list('tx').filter(x=>x.acct===a.id&&x.kind==='expense'&&x.date<=PO.addDays(PO.today(),-((d-(a.stmtDay||1)+31)%31))).reduce((s,x)=>s+x.amt,0); const minDue=Math.round(Math.max(0,bal)*((a.minPct||5)/100)); return `Statement ${PO.fmt(Math.min(stmt,Math.max(0,bal)),a.cur,{force:true})} · min due ${PO.fmt(minDue,a.cur,{force:true})} in ${dueIn} days · next statement in ${stmtIn} days · ${a.limit?Math.round(Math.max(0,bal)/a.limit*100)+'% of limit':''}`; };
PO.loanInfo = a => { if(!a.principal) return 'Loan'; const r=(a.apr||0)/1200, n=a.tenure||12, P=a.principal; const emi=r?Math.round(P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1)):Math.round(P/n); const paidMonths=Math.max(0,Math.min(n, Math.floor(PO.daysBetween(a.start||PO.today(),PO.today())/30))); const totalInterest=emi*n-P; return `EMI ${PO.fmt(emi,a.cur,{force:true})} · ${n-paidMonths} of ${n} left · total interest ${PO.fmt(totalInterest,a.cur,{force:true})}`; };
PO.acctForm = (a={}) => { const isNew=!a.id; PO.form({title:isNew?'New account':a.name, values:{name:a.name||'', type:a.type||'bank', cur:a.cur||PO.cur(), opening:a.opening??0, openDate:a.openDate||PO.today(), includeNW:a.includeNW!==false, includeBudget:a.includeBudget!==false, passThrough:a.passThrough||'', limit:a.limit??null, stmtDay:a.stmtDay||1, dueDay:a.dueDay||20, minPct:a.minPct||5, apr:a.apr||0, principal:a.principal??null, tenure:a.tenure||12, start:a.start||PO.today()}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'type',label:'Type',type:'select',options:['cash','bank','wallet','card','prepaid','loan','receivable','investment','asset','liability','other'].map(v=>({v,l:v}))},{k:'cur',label:t('currency'),type:'select',options:Object.keys(PO.CUR).map(c=>({v:c,l:`${c} (${PO.dec(c)} decimals)`}))},{k:'opening',label:'Opening balance (negative for debt)',type:'number'},{k:'openDate',label:'Opening date',type:'date'},{k:'includeNW',label:`Include in ${t('net_worth').toLowerCase()}`,type:'toggle'},{k:'includeBudget',label:'Include in budgets',type:'toggle'},{k:'passThrough',label:'Pays from (wallet alias)',type:'select',options:[{v:'',l:'No, holds its own balance'},...H.acctOptions(a.id)],hidden:v=>v.type!=='wallet',hint:'Payments post to the linked bank; no double counting'},{k:'limit',label:'Credit limit',type:'money',hidden:v=>v.type!=='card'},{k:'stmtDay',label:'Statement day',type:'number',min:1,max:31,hidden:v=>v.type!=='card'},{k:'dueDay',label:'Payment due day',type:'number',min:1,max:31,hidden:v=>v.type!=='card'},{k:'minPct',label:'Minimum due %',type:'number',min:0,max:100,hidden:v=>v.type!=='card'},{k:'apr',label:'Interest % per year',type:'number',hidden:v=>v.type!=='card'&&v.type!=='loan'},{k:'principal',label:'Principal',type:'money',hidden:v=>v.type!=='loan'},{k:'tenure',label:'Tenure (months)',type:'number',hidden:v=>v.type!=='loan'},{k:'start',label:'First instalment',type:'date',hidden:v=>v.type!=='loan'}], onChange:(ev,form,vals)=>{ if(vals.type!==PO.form_lastType){ PO.form_lastType=vals.type; const s=PO.ui.sheets[PO.ui.sheets.length-1]; Object.assign(s.data.values, vals); PO.rerenderSheet(); } }, onSave:v=>{ const d=PO.dec(v.cur); const patch={name:v.name,type:v.type,cur:v.cur,opening:Math.round((v.opening||0)*Math.pow(10,d)),openDate:v.openDate,includeNW:v.includeNW,includeBudget:v.includeBudget,passThrough:v.type==='wallet'?v.passThrough||null:null,limit:v.limit,stmtDay:v.stmtDay,dueDay:v.dueDay,minPct:v.minPct,apr:v.apr,principal:v.principal,tenure:v.tenure,start:v.start}; const gid=PO.group(()=>PO.commit('accts',a.id||PO.uid('a'),patch)); H.afterWrite(isNew?'Account added':'Saved', gid); }, onDelete:isNew?null:()=>PO.acctDelete(a), actions:isNew?[]:[{k:'arch',label:a.archived?'Unarchive':t('archive'),run:()=>{ PO.commit('accts',a.id,{archived:!a.archived},'archive'); PO.go('accounts'); PO.toast(a.archived?'Restored':'Archived. History kept.'); return 'close'; }}] }); PO.form_lastType=a.type||'bank'; };
PO.acctDelete = a => { const n=PO.list('tx').filter(x=>x.acct===a.id||x.toAcct===a.id).length; const others=H.acctOptions(a.id); PO.form({title:`${t('delete')} ${a.name}`, intro:n?`${n} transactions use this account. Choose where they go.`:'No transactions use this account.', values:{mode:n&&others.length?'move':'delete', to:others[0]?.v||''}, fields:[{k:'mode',label:'Transactions',type:'chips',options:[{v:'move',l:'Move to another account'},{v:'delete',l:'Delete them too (to Trash)'}],hidden:()=>!n},{k:'to',label:'Move to',type:'select',options:others,hidden:v=>!n||v.mode!=='move'}], saveLabel:t('delete'), onSave:v=>{ const gid=PO.group(()=>{ PO.list('tx').filter(x=>x.acct===a.id||x.toAcct===a.id).forEach(x=>{ if(v.mode==='move'&&v.to) PO.commit('tx',x.id,{acct:x.acct===a.id?v.to:x.acct, toAcct:x.toAcct===a.id?v.to:x.toAcct},'reassign'); else PO.remove('tx',x.id); }); PO.remove('accts',a.id); }); PO.go('accounts'); PO.toast('Account deleted (Trash, 30 days)', gid); } }); };
PO.ACT['acct-add'] = () => PO.acctForm();
PO.ACT['acct-edit'] = b => PO.acctForm(PO.get('accts',b.dataset.id));
PO.ACT['acct-unarchive'] = b => { PO.commit('accts',b.dataset.id,{archived:false},'archive'); PO.render(); };
PO.ACT['link-add'] = () => { const pk=PO.pack(); PO.form({title:'Link a bank (simulated consent)', intro:`Provider for ${pk.name}: ${pk.id==='IN'?'Account Aggregator (via a licensed TSP)':pk.id==='PH'?'BSP Open Finance':pk.id==='US'?'Plaid':pk.id==='GB'||pk.id==='DE'?'TrueLayer':pk.id==='BR'?'Pluggy':pk.id==='AU'?'Basiq':'regional aggregator'}. You choose accounts and a consent period; tokens never touch the phone.`, values:{inst:'', acct:(PO.list('accts').find(a=>a.type==='bank')||{}).id, days:90}, fields:[{k:'inst',label:'Institution',type:'text',required:true,datalist:pk.apps},{k:'acct',label:'Map to account',type:'select',options:H.acctOptions()},{k:'days',label:'Consent period (days)',type:'number',min:1,max:365}], saveLabel:'Give consent', onSave:v=>{ if(!PO.state.settings.plus){ PO.openSheet('plus',{reason:'Bank auto-sync is the one Plus feature because every fetch has a fee.'}); return false; } PO.commit('links',PO.uid('lk'),{institution:v.inst, provider:pk.id==='IN'?'Account Aggregator':'Open banking', accts:[v.acct], consentExpiry:PO.addDays(PO.today(),v.days), lastFetch:PO.today(), status:'ok'}); PO.render(); PO.toast('Linked. First fetch queued.'); } }); };
PO.ACT['link-fetch'] = b => { const l=PO.get('links',b.dataset.id); const acct=l.accts[0]; const n=1+Math.floor(Math.random()*3); const names=['Grocery mart','Fuel station','Pharmacy']; for(let i=0;i<n;i++){ PO.commit('review',PO.uid('rv'),{rawText:`${l.institution} · debit ${names[i]}`, amt:PO.toMinor(200+i*150,PO.cur()), cur:PO.cur(), kind:'expense', acct, cat:PO.suggestCat(names[i])||'uncat', payee:names[i], source:l.institution, date:PO.addDays(PO.today(),-i), time:'12:00', confidence:0.9},'capture'); } PO.commit('links',l.id,{lastFetch:PO.today(),status:'ok',error:null},'fetch'); PO.render(); PO.toast(`${n} new transactions in review`); };
PO.ACT['link-reconsent'] = b => { PO.commit('links',b.dataset.id,{consentExpiry:PO.addDays(PO.today(),90),status:'ok',error:null},'consent'); PO.render(); PO.toast('Consent renewed for 90 days'); };
PO.ACT['link-disconnect'] = b => { const l=PO.get('links',b.dataset.id); PO.confirmSheet(`Disconnect ${l.institution}?`, 'Fetched transactions stay in your book. The provider deletes its copy.', ()=>{ const gid=PO.group(()=>PO.remove('links',l.id)); H.afterWrite('Disconnected', gid); }); };

/* ---------- account detail: balance history, reconcile, statement, set balance */
PO.SCREENS.account = { render:(pr)=>{ const a=PO.get('accts',pr.id); if(!a) return H.err('Account not found','',`<button class="btn sm ghost" data-go="accounts">${t('accounts')}</button>`); const bal=PO.balance(a.id); const txs=PO.list('tx').filter(x=>x.acct===a.id||x.toAcct===a.id).sort((x,y)=>(y.date+(y.time||'')).localeCompare(x.date+(x.time||''))); const pts=[]; for(let i=29;i>=0;i--){ const d=PO.addDays(PO.today(),-i); pts.push({d, b:PO.balance(a.id,d)}); } const mn=Math.min(...pts.map(p=>p.b)), mx=Math.max(...pts.map(p=>p.b)); const sp=Math.max(1,mx-mn); const path=pts.map((p,i)=>`${i===0?'M':'L'}${(i/29*300+10).toFixed(1)} ${(70-(p.b-mn)/sp*55).toFixed(1)}`).join(' '); const pendingN=txs.filter(x=>x.status==='pending').length; const unrec=txs.filter(x=>x.status!=='reconciled').length;
  return `${pr.embedded?'':H.hdr(a.name, `${a.type} · ${a.cur}${a.passThrough?` · pays from ${PO.acctName(a.passThrough)}`:''}`, `<button class="pill" data-act="acct-edit" data-id="${a.id}">${t('edit')}</button>`, t('accounts'))}
  <div class="card"><div class="amtbox" style="text-align:start;padding:0;font-size:30px">${esc(PO.fmt(bal,a.cur))}</div><div class="sub">${a.type==='card'?esc(PO.cardInfo(a)):a.type==='loan'?esc(PO.loanInfo(a)):`${pendingN} pending · ${unrec} not reconciled`}</div><svg viewBox="0 0 320 80" width="100%" height="80" role="img" aria-label="Balance over the last 30 days"><path d="${path}" fill="none" stroke="var(--accent)" stroke-width="2"/><text x="10" y="78" font-size="10" fill="var(--muted)">30 days ago</text><text x="310" y="78" font-size="10" text-anchor="end" fill="var(--muted)">today</text></svg>
  <div class="menu">${a.type==='cash'?`<button class="chip small" data-act="acct-reconcile" data-id="${a.id}">${t('count_cash')}</button>`:`<button class="chip small" data-act="acct-reconcile" data-id="${a.id}">${t('reconcile')} to statement</button>`}<button class="chip small" data-act="acct-setbal" data-id="${a.id}">Set balance today</button><button class="chip small" data-go="transactions" ${H.p({acct:a.id})}>${t('search')}</button>${a.type==='card'?`<button class="chip small" data-act="card-pay" data-id="${a.id}">Pay card bill</button>`:''}${a.type==='loan'?`<button class="chip small" data-act="loan-whatif" data-id="${a.id}">Prepay what-if</button>`:''}</div></div>
  <div class="sec">Transactions · ${txs.length}</div><div class="card list">${txs.length?txs.slice(0,40).map(x=>H.txRow(x,{showDate:true})).join(''):H.empty('No transactions','')}</div>`; } };
PO.ACT['acct-reconcile'] = b => { const a=PO.get('accts',b.dataset.id); const bal=PO.balance(a.id); PO.form({title:a.type==='cash'?t('count_cash'):`${t('reconcile')} ${a.name}`, intro:a.type==='cash'?`The book says ${PO.fmt(bal,a.cur,{force:true})}. Count the notes and coins; the difference posts as "${t('unrecorded')}" so the books always balance.`:`The book says ${PO.fmt(bal,a.cur,{force:true})}. Enter the statement balance; matching items become reconciled and locked.`, values:{counted:null, date:PO.today()}, fields:[{k:'counted',label:a.type==='cash'?'Counted amount':'Statement balance (negative for a card balance owed)',type:'money',required:true,autofocus:true},{k:'date',label:'As of',type:'date'}], onSave:v=>{ const target = a.type==='card'||a.type==='loan' ? -Math.abs(v.counted) : v.counted; const diff=target-PO.balance(a.id,v.date); const gid=PO.group(()=>{ if(diff!==0) PO.commit('tx',PO.uid('t'),{kind:a.type==='cash'&&diff<0?'expense':'adjustment', dir:diff>0?'in':'out', amt:Math.abs(diff), cur:a.cur, acct:a.id, cat:a.type==='cash'&&diff<0?PO.cid(PO.state.currentProfile,'unrec'):PO.cid(PO.state.currentProfile,'adj'), payee:a.type==='cash'?t('unrecorded'):'Reconcile adjustment', date:v.date, status:'reconciled', source:'reconcile', tags:[], splits:[], attachments:[]},'create'); PO.list('tx').filter(x=>(x.acct===a.id||x.toAcct===a.id)&&x.date<=v.date&&x.status!=='reconciled').forEach(x=>PO.commit('tx',x.id,{status:'reconciled'},'reconcile')); }); H.afterWrite(diff===0?'Matches the book. All items reconciled.':`Difference ${PO.fmt(Math.abs(diff),a.cur,{force:true})} posted${a.type==='cash'&&diff<0?' as unrecorded cash spend':''}.`, gid); } }); };
PO.ACT['acct-setbal'] = b => { const a=PO.get('accts',b.dataset.id); PO.form({title:'Set balance today', values:{bal:PO.balance(a.id)}, fields:[{k:'bal',label:'Balance',type:'money',required:true}], onSave:v=>{ const diff=v.bal-PO.balance(a.id); if(!diff){ PO.toast('Already matches'); return; } const gid=PO.group(()=>PO.commit('tx',PO.uid('t'),{kind:'adjustment',dir:diff>0?'in':'out',amt:Math.abs(diff),cur:a.cur,acct:a.id,cat:PO.cid(PO.state.currentProfile,'adj'),payee:'Balance adjustment',date:PO.today(),status:'cleared',source:'adjust',tags:[],splits:[],attachments:[]},'create')); H.afterWrite('Adjustment posted', gid); } }); };
PO.ACT['card-pay'] = b => { const a=PO.get('accts',b.dataset.id); const bal=-PO.balance(a.id); PO.form({title:`Pay ${a.name}`, values:{amt:Math.max(0,bal), from:(PO.list('accts').find(x=>x.type==='bank')||{}).id}, fields:[{k:'amt',label:t('amount'),type:'money',required:true},{k:'from',label:t('from'),type:'select',options:H.acctOptions(a.id)}], onSave:v=>{ const gid=PO.group(()=>PO.commit('tx',PO.uid('t'),{kind:'transfer',amt:v.amt,cur:a.cur,acct:v.from,toAcct:a.id,date:PO.today(),note:'Card payment',status:'cleared',source:'manual',tags:[],splits:[],attachments:[]},'create')); H.afterWrite('Card paid', gid); } }); };
PO.ACT['loan-whatif'] = b => { const a=PO.get('accts',b.dataset.id); const r=(a.apr||0)/1200, n=a.tenure||12, P=a.principal||0; const emi=r?P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1):P/n; const sim=extra=>{ let bal=P, m=0, interest=0; while(bal>0&&m<600){ const i=bal*r; interest+=i; bal=bal+i-emi-extra; m++; } return {m, interest:Math.round(interest)}; }; const base=sim(0); PO.form({title:'Prepayment what-if', values:{extra:Math.round(emi*0.2)}, fields:[{k:'extra',label:'Extra per month',type:'money'},{k:'out',label:'',type:'html',html:v=>{ const s=sim(v.extra||0); return `<div class="card" style="background:var(--sunk)"><div class="row"><div class="t">Now</div><div>${base.m} months · interest ${PO.fmt(base.interest,a.cur,{force:true})}</div></div><div class="row"><div class="t">With extra</div><div>${s.m} months · interest ${PO.fmt(s.interest,a.cur,{force:true})}</div></div><div class="row"><div class="t">Saves</div><div class="amt in">${PO.fmt(base.interest-s.interest,a.cur,{force:true})}</div></div></div>`; }}], onChange:(ev,form,vals)=>{ const s=PO.ui.sheets[PO.ui.sheets.length-1]; Object.assign(s.data.values, vals); PO.rerenderSheet(); }, saveLabel:t('close'), onSave:()=>{} }); };

/* ---------- categories: tree, CRUD, merge, archive, reassign on delete */
PO.SCREENS.categories = { render:(pr)=>{ const kind=pr.kind||'expense'; const cats=PO.list('cats').filter(c=>c.kind===kind&&!c.archived); const usage={}; PO.list('tx').forEach(x=>{ usage[x.cat]=(usage[x.cat]||0)+1; (x.splits||[]).forEach(s=>{ usage[s.cat]=(usage[s.cat]||0)+1; }); }); const li=(c,lvl)=>`<li class="${lvl===1?'sub':lvl===2?'sub2':''}"><span class="nm">${esc(c.name)} ${c.excluded?'<span class="pill">excluded</span>':''}<span class="sub"> · ${usage[c.id]||0}</span></span><button class="ic-btn" data-act="cat-edit" data-id="${c.id}">${t('edit')}</button><button class="ic-btn" data-act="cat-add" data-parent="${c.id}" aria-label="Add subcategory" ${lvl>=2?'disabled':''}>+</button></li>`; const tree=cats.filter(c=>!c.parent).map(r=>li(r,0)+cats.filter(c=>c.parent===r.id).map(c=>li(c,1)+cats.filter(g=>g.parent===c.id).map(g=>li(g,2)).join('')).join('')).join('');
  return `${H.hdr(t('categories'), `${cats.length} ${kind} · three levels`, `<button class="pill acc" data-act="cat-add" data-parent="">+ New</button>`, t('home'))}<div class="chips" style="margin-bottom:8px"><button class="chip small" data-go="categories" ${H.p({kind:'expense'})} aria-pressed="${kind==='expense'}">${t('expense')}</button><button class="chip small" data-go="categories" ${H.p({kind:'income'})} aria-pressed="${kind==='income'}">${t('income')}</button><button class="chip small" data-act="cat-reset">Reset defaults (keeps custom)</button><button class="chip small" data-go="tags">${t('tags')}</button></div><div class="card"><ul class="tree">${tree||'<li>'+H.empty('No categories','')+'</li>'}</ul></div>${PO.list('cats').filter(c=>c.archived&&c.kind===kind).length?`<div class="sec">Archived</div><div class="chips">${PO.list('cats').filter(c=>c.archived&&c.kind===kind).map(c=>`<button class="chip small" data-act="cat-unarchive" data-id="${c.id}">↩ ${esc(c.name)}</button>`).join('')}</div>`:''}`; } };
PO.catForm = (c={}, parent='') => { const isNew=!c.id; const kind=c.kind||(parent?PO.get('cats',parent).kind:(PO.ui.params.kind||'expense')); const parents=PO.list('cats').filter(x=>x.kind===kind&&!x.archived&&x.id!==c.id&&(!x.parent||!PO.get('cats',x.parent)?.parent)); PO.form({title:isNew?'New category':c.name, values:{name:c.name||'', parent:c.parent||parent||'', excluded:!!c.excluded, defAcct:c.defAcct||'', alerts:c.alerts||''}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'parent',label:'Parent',type:'select',options:[{v:'',l:'Top level'},...parents.map(p=>({v:p.id,l:PO.catPath(p.id)}))]},{k:'excluded',label:'Exclude from spend reports and budgets',type:'toggle',hint:'For transfers, savings, reimbursables'},{k:'defAcct',label:'Default account',type:'select',options:[{v:'',l:'None'},...H.acctOptions()]}], onSave:v=>{ const gid=PO.group(()=>PO.commit('cats',c.id||PO.uid('c'),{name:v.name,kind,parent:v.parent||null,excluded:v.excluded,defAcct:v.defAcct||null,key:c.key||null})); H.afterWrite(isNew?'Category added':'Saved', gid); }, onDelete:isNew?null:()=>PO.catDelete(c), actions:isNew?[]:[{k:'merge',label:'Merge into…',run:()=>{ PO.closeSheet(); PO.catMerge(c); }},{k:'arch',label:t('archive'),run:()=>{ PO.commit('cats',c.id,{archived:true},'archive'); PO.render(); PO.toast('Archived; history keeps the name'); return 'close'; }}] }); };
PO.catMerge = c => { const targets=PO.list('cats').filter(x=>x.kind===c.kind&&x.id!==c.id&&!PO.catDesc(c.id).includes(x.id)); PO.form({title:`Merge ${c.name} into…`, intro:'All transactions, splits, rules and envelopes move to the target. The source is archived.', fields:[{k:'to',label:'Target',type:'select',options:targets.map(x=>({v:x.id,l:PO.catPath(x.id)})),required:true}], saveLabel:'Merge', onSave:v=>{ const ids=PO.catDesc(c.id); const gid=PO.group(()=>{ PO.list('tx').forEach(x=>{ let ch=false; const patch={}; if(ids.includes(x.cat)){ patch.cat=v.to; ch=true; } if((x.splits||[]).some(s=>ids.includes(s.cat))){ patch.splits=x.splits.map(s=>ids.includes(s.cat)?{...s,cat:v.to}:s); ch=true; } if(ch) PO.commit('tx',x.id,patch,'merge'); }); PO.list('rules').forEach(r=>{ if(ids.includes((r.act||{}).cat)) PO.commit('rules',r.id,{act:{...r.act,cat:v.to}},'merge'); }); PO.list('envs').forEach(e=>{ if(ids.includes(e.cat)) PO.commit('envs',e.id,{cat:v.to},'merge'); }); ids.forEach(id=>PO.commit('cats',id,{archived:true, mergedInto:v.to},'merge')); }); H.afterWrite(`Merged into ${PO.catName(v.to)}`, gid); } }); };
PO.catDelete = c => { const ids=PO.catDesc(c.id); const n=PO.list('tx').filter(x=>ids.includes(x.cat)||(x.splits||[]).some(s=>ids.includes(s.cat))).length; const targets=PO.list('cats').filter(x=>x.kind===c.kind&&!ids.includes(x.id)&&!x.archived); PO.form({title:`${t('delete')} ${c.name}`, intro:n?`${n} transactions use this category or its children. Reassign them first.`:'Not used by any transaction.', values:{to:targets.find(x=>x.key==='uncat')?.id||targets[0]?.v}, fields:[{k:'to',label:'Reassign to',type:'select',options:targets.map(x=>({v:x.id,l:PO.catPath(x.id)})),hidden:()=>!n}], saveLabel:t('delete'), onSave:v=>{ const gid=PO.group(()=>{ if(n){ PO.list('tx').forEach(x=>{ const patch={}; let ch=false; if(ids.includes(x.cat)){ patch.cat=v.to; ch=true; } if((x.splits||[]).some(s=>ids.includes(s.cat))){ patch.splits=x.splits.map(s=>ids.includes(s.cat)?{...s,cat:v.to}:s); ch=true; } if(ch) PO.commit('tx',x.id,patch,'reassign'); }); } ids.forEach(id=>PO.remove('cats',id)); }); H.afterWrite('Deleted (Trash, 30 days)', gid); } }); };
PO.ACT['cat-add'] = b => PO.catForm({}, b.dataset.parent||'');
PO.ACT['cat-edit'] = b => PO.catForm(PO.get('cats',b.dataset.id));
PO.ACT['cat-unarchive'] = b => { PO.commit('cats',b.dataset.id,{archived:false},'archive'); PO.render(); };
PO.ACT['cat-reset'] = () => { const pid=PO.state.currentProfile; let n=0; PO.group(()=>PO.DEFAULT_CATS.forEach(([key,kind,name,parent,flag])=>{ const id=PO.cid(pid,key); if(!PO.get('cats',id)){ PO.commit('cats',id,{key,kind,name,parent:parent?PO.cid(pid,parent):null,excluded:flag==='x'},'reset'); n++; } else if(PO.get('cats',id).deleted_at||PO.get('cats',id).archived){ PO.commit('cats',id,{deleted_at:null,archived:false},'reset'); n++; } })); PO.render(); PO.toast(`${n} default categories restored`); };
PO.SCREENS.tags = { render:()=>`${H.hdr(t('tags'),'',`<button class="pill acc" data-act="tag-add">+ Tag</button>`, t('categories'))}<div class="card list">${PO.list('tags').map(tg=>{ const n=PO.list('tx').filter(x=>(x.tags||[]).includes(tg.name)).length; return `<div class="row"><div><div class="t"># ${esc(tg.name)}</div><div class="m">${n} transactions</div></div><div class="menu"><button class="chip small" data-go="transactions" ${H.p({tag:tg.name})}>${t('search')}</button><button class="chip small" data-act="tag-rename" data-id="${tg.id}">Rename</button><button class="chip small" data-act="tag-del" data-id="${tg.id}">${t('delete')}</button></div></div>`; }).join('')||H.empty('No tags','Add tags from any transaction.')}</div>` };
PO.ACT['tag-add'] = () => PO.form({title:'New tag', fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true}], onSave:v=>{ PO.commit('tags',PO.uid('tg'),{name:v.name.trim()}); PO.render(); }});
PO.ACT['tag-rename'] = b => { const tg=PO.get('tags',b.dataset.id); PO.form({title:'Rename tag', values:{name:tg.name}, fields:[{k:'name',label:'Name',type:'text',required:true}], onSave:v=>{ const gid=PO.group(()=>{ PO.list('tx').filter(x=>(x.tags||[]).includes(tg.name)).forEach(x=>PO.commit('tx',x.id,{tags:x.tags.map(z=>z===tg.name?v.name.trim():z)},'rename')); PO.commit('tags',tg.id,{name:v.name.trim()},'rename'); }); H.afterWrite('Renamed everywhere', gid); } }); };
PO.ACT['tag-del'] = b => { const tg=PO.get('tags',b.dataset.id); const gid=PO.group(()=>{ PO.list('tx').filter(x=>(x.tags||[]).includes(tg.name)).forEach(x=>PO.commit('tx',x.id,{tags:x.tags.filter(z=>z!==tg.name)},'untag')); PO.remove('tags',tg.id); }); H.afterWrite('Tag removed', gid); };

/* ---------- payees */
PO.SCREENS.payees = { render:(pr)=>{ const q=(pr.q||'').toLowerCase(); const ps=PO.list('payees').map(p=>{ const tx=PO.list('tx').filter(x=>x.payeeId===p.id); return {p, n:tx.length, sum:tx.filter(x=>x.kind==='expense').reduce((s,x)=>s+PO.toBase(x.amt,x.cur),0), last:tx.map(x=>x.date).sort().pop()}; }).filter(x=>!q||x.p.name.toLowerCase().includes(q)||(x.p.aliases||[]).some(a=>a.toLowerCase().includes(q))).sort((a,b)=>b.n-a.n);
  return `${H.hdr(t('payees'), `${ps.length} · merge duplicates, set default categories`, `<button class="pill acc" data-act="payee-add">+ New</button>`, t('home'))}<form data-psearch style="margin-bottom:8px"><input class="inp" id="pq" placeholder="Search payees" value="${esc(pr.q||'')}" aria-label="Search payees"></form><div class="card list">${ps.map(({p,n,sum,last})=>`<div class="row"><div style="min-width:0"><div class="t">${esc(p.name)} ${(p.aliases||[]).length?`<span class="pill">${p.aliases.length} aliases</span>`:''}</div><div class="m">${n} × · ${PO.fmt(sum)} · ${p.defaultCat?PO.catName(p.defaultCat):'no default'}${last?` · last ${PO.relDate(last)}`:''}</div></div><div class="menu"><button class="chip small" data-go="transactions" ${H.p({q:p.name})}>${t('search')}</button><button class="chip small" data-act="payee-edit" data-id="${p.id}">${t('edit')}</button></div></div>`).join('')||H.empty('No payees','Payees are created as you add transactions.')}</div>`; }, after:()=>{ const f=document.querySelector('form[data-psearch]'); if(f) f.addEventListener('submit',ev=>{ ev.preventDefault(); PO.go('payees',{q:$('#pq').value}); }); } };
PO.payeeForm = (p={}) => { const isNew=!p.id; const others=PO.list('payees').filter(x=>x.id!==p.id); PO.form({title:isNew?'New payee':p.name, values:{name:p.name||'', aliases:(p.aliases||[]).join(', '), defaultCat:p.defaultCat||'', website:p.website||'', notes:p.notes||''}, fields:[{k:'name',label:'Display name',type:'text',required:true,autofocus:true},{k:'aliases',label:'Aliases (raw names seen on statements)',type:'text',placeholder:'ZOMATO LTD, zomato*order'},{k:'defaultCat',label:'Default category',type:'select',options:[{v:'',l:'None'},...H.catOptions('expense'),...H.catOptions('income')]},{k:'website',label:'Website',type:'text'},{k:'notes',label:t('note'),type:'textarea'}], onSave:v=>{ const gid=PO.group(()=>PO.commit('payees',p.id||PO.uid('py'),{name:v.name.trim(),aliases:v.aliases.split(',').map(s=>s.trim()).filter(Boolean),defaultCat:v.defaultCat||null,website:v.website,notes:v.notes})); H.afterWrite('Saved', gid); }, onDelete:isNew?null:()=>{ const n=PO.list('tx').filter(x=>x.payeeId===p.id).length; PO.confirmSheet(`${t('delete')} ${p.name}?`, n?`${n} transactions keep the name as plain text.`:'Not used.', ()=>{ const gid=PO.group(()=>{ PO.list('tx').filter(x=>x.payeeId===p.id).forEach(x=>PO.commit('tx',x.id,{payeeId:null,payee:p.name},'unlink')); PO.remove('payees',p.id); }); H.afterWrite('Deleted', gid); }); }, actions:isNew?[]:[{k:'merge',label:'Merge into…',run:()=>{ PO.closeSheet(); PO.form({title:`Merge ${p.name} into…`, fields:[{k:'to',label:'Target payee',type:'select',options:others.map(x=>({v:x.id,l:x.name})),required:true}], saveLabel:'Merge', onSave:v=>{ const to=PO.get('payees',v.to); const gid=PO.group(()=>{ PO.list('tx').filter(x=>x.payeeId===p.id).forEach(x=>PO.commit('tx',x.id,{payeeId:to.id,payee:to.name},'merge')); PO.commit('payees',to.id,{aliases:[...new Set([...(to.aliases||[]),p.name,...(p.aliases||[])])]},'merge'); PO.remove('payees',p.id,'merge'); }); H.afterWrite(`Merged into ${to.name}`, gid); } }); }}] }); };
PO.ACT['payee-add'] = () => PO.payeeForm();
PO.ACT['payee-edit'] = b => PO.payeeForm(PO.get('payees',b.dataset.id));

/* ---------- rules */
PO.SCREENS.rules = { render:()=>{ const rules=PO.list('rules').sort((a,b)=>(a.order||0)-(b.order||0)); const conflicts=[]; const sample=PO.list('tx').slice(0,200); rules.forEach((r,i)=>rules.slice(i+1).forEach(r2=>{ if(sample.some(x=>PO.matchRule(r,x)&&PO.matchRule(r2,x)) && JSON.stringify(r.act)!==JSON.stringify(r2.act)) conflicts.push([r,r2]); }));
  return `${H.hdr(t('rules'), 'First match wins unless a rule continues. Corrections create draft rules after 2 and enable after 3.', `<div style="display:flex;gap:6px"><button class="pill" data-act="rules-export">${t('export')}</button><button class="pill acc" data-act="rule-add">+ Rule</button></div>`, t('home'))}
  ${conflicts.length?`<div class="card err"><b>${conflicts.length} conflicts</b><div class="sub">${conflicts.slice(0,3).map(([a,b])=>`${esc(a.name)} vs ${esc(b.name)}`).join('; ')}. The earlier rule wins; reorder if that is wrong.</div></div>`:''}
  <div class="card list">${rules.length?rules.map((r,i)=>`<div class="row"><div style="min-width:0"><div class="t">${esc(r.name)} ${r.learned?'<span class="pill">learned</span>':''} ${r.enabled===false?'<span class="pill">draft</span>':''}</div><div class="m">${esc(Object.entries(r.cond||{}).map(([k,v])=>`${k}: ${v}`).join(', '))} → ${esc(Object.entries(r.act||{}).map(([k,v])=>k==='cat'?`category ${PO.catName(v)}`:`${k}: ${v}`).join(', '))}</div></div><div class="menu"><button class="ic-btn" data-act="rule-move" data-id="${r.id}" data-d="-1" aria-label="Move up" ${i===0?'disabled':''}>↑</button><button class="ic-btn" data-act="rule-move" data-id="${r.id}" data-d="1" aria-label="Move down" ${i===rules.length-1?'disabled':''}>↓</button><button class="sw" role="switch" aria-checked="${r.enabled!==false}" data-act="rule-toggle" data-id="${r.id}" aria-label="Enabled"></button><button class="chip small" data-act="rule-edit" data-id="${r.id}">${t('edit')}</button></div></div>`).join(''):H.empty('No rules yet','Rules categorise captured transactions automatically.')}</div>`; } };
PO.ruleForm = (r={}) => { const isNew=!r.id; const c=r.cond||{}, a=r.act||{}; PO.form({title:isNew?'New rule':r.name, values:{name:r.name||'', payeeContains:c.payeeContains||'', payeeRegex:c.payeeRegex||'', kind:c.kind||'', acct:c.acct||'', source:c.source||'', min:c.min??null, max:c.max??null, cat:a.cat||'', tags:(a.tags||[]).join(', '), payeeName:a.payeeName||'', exclude:!!a.excludeBudget, priv:!!a.private, autopost:!!a.autopost, cont:!!r.cont}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'payeeContains',label:'Payee contains',type:'text'},{k:'payeeRegex',label:'Payee matches regex',type:'text'},{k:'kind',label:'Type',type:'select',options:[{v:'',l:'Any'},{v:'expense',l:t('expense')},{v:'income',l:t('income')}]},{k:'acct',label:t('account'),type:'select',options:[{v:'',l:'Any'},...H.acctOptions()]},{k:'source',label:'Source app',type:'text',datalist:PO.pack().apps},{k:'min',label:'Amount at least',type:'money'},{k:'max',label:'Amount at most',type:'money'},{k:'cat',label:'Set category',type:'select',options:[{v:'',l:'Leave as is'},...H.catOptions('expense'),...H.catOptions('income')]},{k:'tags',label:'Add tags',type:'text'},{k:'payeeName',label:'Rename payee to',type:'text'},{k:'exclude',label:'Exclude from budgets',type:'toggle'},{k:'priv',label:'Mark private',type:'toggle'},{k:'autopost',label:'Auto-post captured items',type:'toggle'},{k:'cont',label:'Continue to next rule after this one',type:'toggle'},{k:'prev',label:'',type:'html',html:()=>`<button type="button" class="chip small" data-act="form-action" data-k="preview">Preview matches</button> <span class="sub" data-preview></span>`}], actions:[{k:'preview',label:'',run:(v,form)=>{ const rule=build(v); const n=PO.list('tx').filter(x=>PO.matchRule(rule,x)).length; form.querySelector('[data-preview]').textContent=`${n} existing transactions match`; }},...(isNew?[]:[{k:'apply',label:'Apply to past',run:(v)=>{ const rule=build(v); let n=0; const gid=PO.group(()=>PO.list('tx').forEach(x=>{ if(PO.matchRule(rule,x)&&Object.keys(rule.act).length){ const patch={}; if(rule.act.cat) patch.cat=rule.act.cat; if(rule.act.tags) patch.tags=[...new Set([...(x.tags||[]),...rule.act.tags])]; if(rule.act.excludeBudget) patch.excludeBudget=true; if(Object.keys(patch).length){ PO.commit('tx',x.id,patch,'rule'); n++; } } })); PO.closeSheet(); H.afterWrite(`Applied to ${n} transactions`, gid); return 'close'; }}])], onSave:v=>{ const rule=build(v); const gid=PO.group(()=>PO.commit('rules',r.id||PO.uid('rule'),{...rule, order:r.order??PO.list('rules').length, enabled:r.enabled!==false, learned:!!r.learned})); H.afterWrite('Rule saved', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('rules',r.id)); H.afterWrite('Rule deleted', gid); } }); function build(v){ const cond={}; if(v.payeeContains) cond.payeeContains=v.payeeContains; if(v.payeeRegex) cond.payeeRegex=v.payeeRegex; if(v.kind) cond.kind=v.kind; if(v.acct) cond.acct=v.acct; if(v.source) cond.source=v.source; if(v.min!=null) cond.min=v.min; if(v.max!=null) cond.max=v.max; const act={}; if(v.cat) act.cat=v.cat; if(v.tags) act.tags=v.tags.split(',').map(s=>s.trim()).filter(Boolean); if(v.payeeName) act.payeeName=v.payeeName; if(v.exclude) act.excludeBudget=true; if(v.priv) act.private=true; if(v.autopost) act.autopost=true; return {name:v.name, cond, act, cont:!!v.cont}; } };
PO.ACT['rule-add'] = () => PO.ruleForm();
PO.ACT['rule-edit'] = b => PO.ruleForm(PO.get('rules',b.dataset.id));
PO.ACT['rule-toggle'] = b => { const r=PO.get('rules',b.dataset.id); PO.commit('rules',r.id,{enabled:r.enabled===false},'toggle'); PO.render(); };
PO.ACT['rule-move'] = b => { const rules=PO.list('rules').sort((a,c)=>(a.order||0)-(c.order||0)); const i=rules.findIndex(r=>r.id===b.dataset.id); const j=i+Number(b.dataset.d); if(j<0||j>=rules.length) return; PO.group(()=>{ PO.commit('rules',rules[i].id,{order:j},'reorder'); PO.commit('rules',rules[j].id,{order:i},'reorder'); }); PO.render(); };
PO.ACT['rules-export'] = () => { PO.form({title:'Rules JSON', fields:[{k:'json',label:'Copy or edit, then import',type:'textarea',code:true,rows:8}], values:{json:JSON.stringify(PO.list('rules').map(({name,cond,act,cont,enabled})=>({name,cond,act,cont,enabled})),null,1)}, saveLabel:'Import this JSON', onSave:v=>{ try{ const arr=JSON.parse(v.json); const gid=PO.group(()=>arr.forEach((r,i)=>PO.commit('rules',PO.uid('rule'),{...r,order:PO.list('rules').length+i}))); H.afterWrite(`Imported ${arr.length} rules`, gid); }catch(e){ PO.toast('Invalid JSON: '+e.message); return false; } } }); };
})(window.PO);
